INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vVJUANA6k8h', 1, '{"title":"1、甘草","description":"<p>1、$u{甘草}</p>\r\n<p>$q{《神农本草经》}：【甘草】味甘。平。主治五藏六府寒热邪气。坚筋骨。长肌肉。倍力。金疮。尰。解毒。久服轻身。延年。生河西川谷。</p>\r\n<p>$q{《名医别录》}：【甘草】无毒。主温中。下气。烦满。短气。伤藏。咳嗽。止渴。通经脉。利血气。解百药毒。为九土之精。安和七十二种石。一千二百种草。一名蜜甘。一名美草。一名蜜草。一名蕗。生河西积沙山及上郡。二月八月除日采根。暴干。十日成。（术干漆苦参为之使。远志。反大戟芫花甘遂海藻。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":0,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '1、$u{甘草} $q{《神农本草经》}：【甘草】味甘。平。主治五藏六府寒热邪气。坚筋骨。长肌肉。倍力。金疮。尰。解毒。久服轻身。延年。生河西川谷。 $q{《名医别录》}：【甘草】无毒。主温中。下气。烦满。短气。伤藏。咳嗽。止渴。通经脉。利血气。解百药毒。为九土之精。安和七十二种石。一千二百种草。一名蜜甘。一名美草。一名蜜草。一名蕗。生河西积沙山及上郡。二月八月除日采根。暴干。十日成。（术干漆苦参为之使。远志。反大戟芫花甘遂海藻。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7S7n1dzieYK', 1, '{"title":"2、桂枝","description":"<p>2、$u{桂枝}</p>\n<p>$q{《神农本草经》}：【牡桂】味辛。温。主治上气咳逆。结气。喉痹。吐吸。利关节。补中益气。久服通神。轻身。不老。生南海山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【牡桂】无毒。主治心痛。胁风。胁痛。温筋通脉。止烦。出汗。生南海。</p>\n<p></p>\n<p>$q{《神农本草经》}：【箘桂】味辛。温。主治百疾。养精神。和颜色。为诸药先聘通使。久服轻身。不老。面生光华媚好。常如童子。生交址桂林山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【菌桂】无毒。生交趾桂林山谷岩崖间。无骨。正圆如竹。立秋采。</p>\n<p></p>\n<p>$q{《名医别录》}：【桂】味甘辛。大热。有毒。主温中。利肝肺气。心腹寒热。冷疾。霍乱。转筋。头痛。腰痛。出汗。止烦。止唾咳嗽鼻齆。能堕胎。坚骨节。通血脉。理疏不足。宣导百药。无所畏。久服神仙。不老。生桂阳。二月七八月十月采皮。阴干。（得人参麦门冬甘草大黄黄芩调中益气。得柴胡紫石英干地黄治吐逆。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":1,"yaoNames":"","aliases":[{"bieming":"桂","name":"桂枝"},{"bieming":"桂心","name":"桂枝"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2、$u{桂枝} $q{《神农本草经》}：【牡桂】味辛。温。主治上气咳逆。结气。喉痹。吐吸。利关节。补中益气。久服通神。轻身。不老。生南海山谷。 $q{《名医别录》}：【牡桂】无毒。主治心痛。胁风。胁痛。温筋通脉。止烦。出汗。生南海。 $q{《神农本草经》}：【箘桂】味辛。温。主治百疾。养精神。和颜色。为诸药先聘通使。久服轻身。不老。面生光华媚好。常如童子。生交址桂林山谷。 $q{《名医别录》}：【菌桂】无毒。生交趾桂林山谷岩崖间。无骨。正圆如竹。立秋采。 $q{《名医别录》}：【桂】味甘辛。大热。有毒。主温中。利肝肺气。心腹寒热。冷疾。霍乱。转筋。头痛。腰痛。出汗。止烦。止唾咳嗽鼻齆。能堕胎。坚骨节。通血脉。理疏不足。宣导百药。无所畏。久服神仙。不老。生桂阳。二月七八月十月采皮。阴干。（得人参麦门冬甘草大黄黄芩调中益气。得柴胡紫石英干地黄治吐逆。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VcvhqvKkSct', 1, '{"title":"3、生姜","description":"<p>3、$u{生姜}[本经未录生姜，仅于干姜条言生者尤良。]</p>\r\n<p>$q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。</p>\r\n<p>$q{《名医别录》}：【生姜】味辛。微温。主治伤寒头痛鼻塞。咳逆上气。止呕吐。生犍为及荆州扬州。九月采。又【生姜】微温。辛。归五藏。去淡。下气。止呕吐。除风邪寒热。久服小志少智。伤心气。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":2,"yaoNames":"","aliases":[{"bieming":"生姜汁","name":"生姜"},{"bieming":"姜","name":"生姜"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '3、$u{生姜}[本经未录生姜，仅于干姜条言生者尤良。] $q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。 $q{《名医别录》}：【生姜】味辛。微温。主治伤寒头痛鼻塞。咳逆上气。止呕吐。生犍为及荆州扬州。九月采。又【生姜】微温。辛。归五藏。去淡。下气。止呕吐。除风邪寒热。久服小志少智。伤心气。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JZ9gTmGblYB', 1, '{"title":"4、大枣","description":"<p>4、$u{大枣}</p>\r\n<p>$q{《神农本草经》}：【大枣】味甘。平。主治心腹邪气。安中。养脾。助十二经。平胃气。通九窍。补少气少津。身中不足。大惊。四肢重。和百药。久服轻身长年。【叶】覆麻黄。能出汗。生河东平泽。</p>\r\n<p>$q{《名医别录》}：【大枣】无毒。补中益气。强力。除烦闷。治心下悬肠澼澼。久服不饥神仙。一名干枣。一名美枣。一名良枣。八月采。暴干。【三岁陈核中仁】燔之。味苦。主治腹痛邪气。【生枣】味甘辛。多食令人多寒热。羸瘦者。不可食。生河东。（杀乌头毒。）又【枣叶】散服使人瘦。久即呕吐。揩热疿疮至良。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":3,"yaoNames":"","aliases":[{"bieming":"枣","name":"大枣"},{"bieming":"枣膏","name":"大枣"},{"bieming":"枣肉","name":"大枣"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '4、$u{大枣} $q{《神农本草经》}：【大枣】味甘。平。主治心腹邪气。安中。养脾。助十二经。平胃气。通九窍。补少气少津。身中不足。大惊。四肢重。和百药。久服轻身长年。【叶】覆麻黄。能出汗。生河东平泽。 $q{《名医别录》}：【大枣】无毒。补中益气。强力。除烦闷。治心下悬肠澼澼。久服不饥神仙。一名干枣。一名美枣。一名良枣。八月采。暴干。【三岁陈核中仁】燔之。味苦。主治腹痛邪气。【生枣】味甘辛。多食令人多寒热。羸瘦者。不可食。生河东。（杀乌头毒。）又【枣叶】散服使人瘦。久即呕吐。揩热疿疮至良。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('axI8tfBmKAx', 1, '{"title":"5、半夏","description":"<p>5、$u{半夏}</p>\r\n<p>$q{《神农本草经》}：【半夏】味辛。平。主治伤寒寒热。心下坚。下气。喉咽肿痛。头眩。胸胀。咳逆。肠鸣。止汗。一名地文。一名水玉。生槐里川谷。</p>\r\n<p>$q{《名医别录》}：【半夏】生微寒熟温。有毒。主消心腹胸中膈痰热满结。咳嗽上气。心下急痛坚痞。时气呕逆。消痈肿。胎堕。治萎黄。悦泽面目。生令人吐。熟令人下。用之汤洗。令滑尽。一名守。一名示姑。生槐里。五月八月采根。暴干。（射干为之使。恶皂荚。畏雄黄生姜干姜秦皮龟甲。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":4,"yaoNames":"地文,水玉,守,示姑","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '5、$u{半夏} $q{《神农本草经》}：【半夏】味辛。平。主治伤寒寒热。心下坚。下气。喉咽肿痛。头眩。胸胀。咳逆。肠鸣。止汗。一名地文。一名水玉。生槐里川谷。 $q{《名医别录》}：【半夏】生微寒熟温。有毒。主消心腹胸中膈痰热满结。咳嗽上气。心下急痛坚痞。时气呕逆。消痈肿。胎堕。治萎黄。悦泽面目。生令人吐。熟令人下。用之汤洗。令滑尽。一名守。一名示姑。生槐里。五月八月采根。暴干。（射干为之使。恶皂荚。畏雄黄生姜干姜秦皮龟甲。反乌头。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ro0664U6sTQ', 1, '{"title":"6、芍药","description":"<p>6、$u{芍药}</p>\r\n<p>$q{《神农本草经》}：【芍药】味苦。平。主治邪气腹痛。除血痹。破坚积。寒热。疝瘕。止痛。利小便。益气。生中岳川谷。</p>\r\n<p>$q{《名医别录》}：【芍药】味酸。微寒。有小毒。主通顺血脉。缓中。散恶血。逐贼血。去水气。利膀胱大小肠。消痈肿。时行寒热。中恶。腹痛。腰痛。一名白木。一名余容。一名犁食。一名解仓。一名铤。生中岳及丘陵。二月八月采根。暴干。（须丸为之使。恶石斛芒消。畏消石鳖甲小蓟。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":5,"yaoNames":"白木,余容,犁食,解仓,铤","aliases":[{"bieming":"白芍药","name":"芍药"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '6、$u{芍药} $q{《神农本草经》}：【芍药】味苦。平。主治邪气腹痛。除血痹。破坚积。寒热。疝瘕。止痛。利小便。益气。生中岳川谷。 $q{《名医别录》}：【芍药】味酸。微寒。有小毒。主通顺血脉。缓中。散恶血。逐贼血。去水气。利膀胱大小肠。消痈肿。时行寒热。中恶。腹痛。腰痛。一名白木。一名余容。一名犁食。一名解仓。一名铤。生中岳及丘陵。二月八月采根。暴干。（须丸为之使。恶石斛芒消。畏消石鳖甲小蓟。反藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0p1dUWRsS6D', 1, '{"title":"7、干姜","description":"<p>7、$u{干姜}</p>\r\n<p>$q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。</p>\r\n<p>$q{《名医别录》}：【干姜】大热。无毒。主治寒冷腹痛。中恶。霍乱。胀满。风邪诸毒。皮肤间结气。止唾血。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":6,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '7、$u{干姜} $q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。 $q{《名医别录》}：【干姜】大热。无毒。主治寒冷腹痛。中恶。霍乱。胀满。风邪诸毒。皮肤间结气。止唾血。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VHE7Y68l232', 1, '{"title":"8、茯苓","description":"<p>8、$u{茯苓}</p>\r\n<p>$q{《神农本草经》}：【茯苓】味甘。平。主胸胁逆气。忧恚。惊邪恐悸。心下结痛。寒热。烦满。咳逆。止口焦舌干。利小便。久服安魂魄养神。不饥。延年。一名伏菟。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【茯苓】无毒。止消渴。好唾。大腹淋沥。膈中痰水。水肿淋结。开胸府。调藏气。伐肾邪。长阴。益气力。保神守中。其有根者。名茯神。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":7,"yaoNames":"伏菟","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '8、$u{茯苓} $q{《神农本草经》}：【茯苓】味甘。平。主胸胁逆气。忧恚。惊邪恐悸。心下结痛。寒热。烦满。咳逆。止口焦舌干。利小便。久服安魂魄养神。不饥。延年。一名伏菟。生太山山谷。 $q{《名医别录》}：【茯苓】无毒。止消渴。好唾。大腹淋沥。膈中痰水。水肿淋结。开胸府。调藏气。伐肾邪。长阴。益气力。保神守中。其有根者。名茯神。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GIXSHBaFv0L', 1, '{"title":"9、人参","description":"<p>9、$u{人参}</p>\r\n<p>$q{《神农本草经》}：【人参】味甘。微寒。主补五藏。安精神。定魂魄。止惊悸。除邪气。明目。开心益智。久服轻身延年。一名人衔。一名鬼盖。生上党山谷。</p>\r\n<p>$q{《名医别录》}：【人参】微温。无毒。主治肠胃中冷。心腹鼓痛。胸胁逆满。霍乱吐逆。调中。止消渴通血脉。破坚积。令人不忘。一名神草。一名人微。一名土精。一名血参。如人形者有神。生上党及辽东。二月四月八月上旬采根。竹刀刮。暴干。无令见风。（茯苓为之使。恶溲疏。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":8,"yaoNames":"人衔,鬼盖,神草,人微,土精,血参","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '9、$u{人参} $q{《神农本草经》}：【人参】味甘。微寒。主补五藏。安精神。定魂魄。止惊悸。除邪气。明目。开心益智。久服轻身延年。一名人衔。一名鬼盖。生上党山谷。 $q{《名医别录》}：【人参】微温。无毒。主治肠胃中冷。心腹鼓痛。胸胁逆满。霍乱吐逆。调中。止消渴通血脉。破坚积。令人不忘。一名神草。一名人微。一名土精。一名血参。如人形者有神。生上党及辽东。二月四月八月上旬采根。竹刀刮。暴干。无令见风。（茯苓为之使。恶溲疏。反藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jT011T7yIVO', 1, '{"title":"10、附子","description":"<p>10、$u{附子}</p>\r\n<p>$q{《神农本草经》}：【附子】味辛。温。主治风寒咳逆。邪气。温中。金创。破癥坚积聚。血瘕。寒湿踒躄。拘挛。膝痛不能行走。生犍为山谷。</p>\r\n<p>$q{《名医别录》}：【附子】味甘。大热。有大毒。主治脚疼冷弱。腰脊风寒。心腹冷痛。霍乱转筋。下痢赤白。坚肌骨。强阴。又堕胎。为百药长。生犍为及广汉。八月采为附子。春采为乌头。（地胆为之使。恶蜈蚣。畏防风甘草黄芪人参乌韭大豆。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":9,"yaoNames":"茛","aliases":[{"bieming":"大附子","name":"附子"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '10、$u{附子} $q{《神农本草经》}：【附子】味辛。温。主治风寒咳逆。邪气。温中。金创。破癥坚积聚。血瘕。寒湿踒躄。拘挛。膝痛不能行走。生犍为山谷。 $q{《名医别录》}：【附子】味甘。大热。有大毒。主治脚疼冷弱。腰脊风寒。心腹冷痛。霍乱转筋。下痢赤白。坚肌骨。强阴。又堕胎。为百药长。生犍为及广汉。八月采为附子。春采为乌头。（地胆为之使。恶蜈蚣。畏防风甘草黄芪人参乌韭大豆。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UIYZOmiE2xW', 1, '{"title":"11、白术","description":"<p>11、$u{白术}（术）</p>\r\n<p>$q{《神农本草经》}：【术】味苦。温。主治风寒湿痹。死肌。痉。疸。止汗。除热。消食。作煎饵。久服轻身。延年。不饥。一名山蓟。生郑山山谷。</p>\r\n<p>$q{《名医别录》}：【术】味甘。无毒。主治大风在身面。风眩头痛。目泪出。消痰水。逐皮间风水结肿。除心下急满。及霍乱。吐下不止。利腰脐间血。益津液。暖胃。消谷。嗜食。一名山姜。一名山连。生郑山汉中南郑。二月三月八月九月采根。暴干。（防风地榆为之使。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":10,"yaoNames":"山蓟,山精","aliases":[{"bieming":"术","name":"白术"},{"bieming":"朮","name":"白术"},{"bieming":"白朮","name":"白术"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '11、$u{白术}（术） $q{《神农本草经》}：【术】味苦。温。主治风寒湿痹。死肌。痉。疸。止汗。除热。消食。作煎饵。久服轻身。延年。不饥。一名山蓟。生郑山山谷。 $q{《名医别录》}：【术】味甘。无毒。主治大风在身面。风眩头痛。目泪出。消痰水。逐皮间风水结肿。除心下急满。及霍乱。吐下不止。利腰脐间血。益津液。暖胃。消谷。嗜食。一名山姜。一名山连。生郑山汉中南郑。二月三月八月九月采根。暴干。（防风地榆为之使。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nxz0hvgpJJf', 1, '{"title":"12、麻黄","description":"<p>12、$u{麻黄}</p>\r\n<p>$q{《神农本草经》}：【麻黄】味苦。温。主治中风伤寒头痛。温疟。发表出汗。去邪热气。止咳逆上气。除寒热。破癥坚积聚。一名龙沙。生晋地。</p>\r\n<p>$q{《名医别录》}：【麻黄】微温。无毒。主治五藏邪气缓急。风胁痛。字乳余疾。止好唾。通腠理。疏伤寒头痛解肌。泄邪恶气。消赤黑斑毒。不可多服。令人虚。一名卑相。一名卑盐。生晋地及河东。立秋采茎。阴干令青。（厚朴为之使。恶辛夷石韦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":11,"yaoNames":"龙沙","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '12、$u{麻黄} $q{《神农本草经》}：【麻黄】味苦。温。主治中风伤寒头痛。温疟。发表出汗。去邪热气。止咳逆上气。除寒热。破癥坚积聚。一名龙沙。生晋地。 $q{《名医别录》}：【麻黄】微温。无毒。主治五藏邪气缓急。风胁痛。字乳余疾。止好唾。通腠理。疏伤寒头痛解肌。泄邪恶气。消赤黑斑毒。不可多服。令人虚。一名卑相。一名卑盐。生晋地及河东。立秋采茎。阴干令青。（厚朴为之使。恶辛夷石韦。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('To31b37bc6Z', 1, '{"title":"13、大黄","description":"<p>13、$u{大黄}</p>\r\n<p>$q{《神农本草经》}：【大黄】味苦。寒。主下瘀血。血闭。寒热。破癥瘕。积聚。留饮宿食。荡涤肠胃。推陈致新。通利水谷道。调中化食。安和五藏。生河西山谷。</p>\r\n<p>$q{《名医别录》}：【大黄】（将军。）大寒。无毒。平胃下气。除痰实。肠间结热。心腹胀满。女子寒血闭胀。小腹痛。诸老血留结。一名黄良。生河西及陇西。二月八月采根。火干。（黄芩为之使。无所畏。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":12,"yaoNames":"将军,川军","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '13、$u{大黄} $q{《神农本草经》}：【大黄】味苦。寒。主下瘀血。血闭。寒热。破癥瘕。积聚。留饮宿食。荡涤肠胃。推陈致新。通利水谷道。调中化食。安和五藏。生河西山谷。 $q{《名医别录》}：【大黄】（将军。）大寒。无毒。平胃下气。除痰实。肠间结热。心腹胀满。女子寒血闭胀。小腹痛。诸老血留结。一名黄良。生河西及陇西。二月八月采根。火干。（黄芩为之使。无所畏。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fd3riAoOlLa', 1, '{"title":"14、黄芩","description":"<p>14、$u{黄芩}</p>\r\n<p>$q{《神农本草经》}：【黄芩】味苦。平。主治诸热。黄疸。肠澼泄痢。逐水。下血闭。恶疮疽蚀。火疡。一名腐肠。生秭归川谷。</p>\r\n<p>$q{《名医别录》}：【黄芩】大寒。无毒。主治痰热。胃中热。小腹绞痛。消谷。利小肠。女子血闭淋露下血。小儿腹痛。一名空肠。一名内虚。一名黄文。一名经芩。一名妬妇。其【子】主肠澼脓血。生秭归及宛朐。三月三日采根。阴干。（得厚朴黄连止腹痛。得五味子牡蒙牡蛎令人有子。得黄芪白蔹赤小豆治鼠瘘。山茱萸龙骨为之使。恶葱实。畏丹参牡丹藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":13,"yaoNames":"腐肠","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '14、$u{黄芩} $q{《神农本草经》}：【黄芩】味苦。平。主治诸热。黄疸。肠澼泄痢。逐水。下血闭。恶疮疽蚀。火疡。一名腐肠。生秭归川谷。 $q{《名医别录》}：【黄芩】大寒。无毒。主治痰热。胃中热。小腹绞痛。消谷。利小肠。女子血闭淋露下血。小儿腹痛。一名空肠。一名内虚。一名黄文。一名经芩。一名妬妇。其【子】主肠澼脓血。生秭归及宛朐。三月三日采根。阴干。（得厚朴黄连止腹痛。得五味子牡蒙牡蛎令人有子。得黄芪白蔹赤小豆治鼠瘘。山茱萸龙骨为之使。恶葱实。畏丹参牡丹藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FRaBwjHoVui', 1, '{"title":"15、枳实","description":"<p>15、$u{枳实}</p>\r\n<p>$q{《神农本草经》}：【枳实】味苦。寒。主治大风在皮肤中。如麻豆苦痒。除寒热。热结。止痢。长肌肉。利五藏。益气。轻身。生河内川泽。</p>\r\n<p>$q{《名医别录》}：【枳实】味酸。微寒。无毒。主除胸胁淡癖。逐停水。破结实。消胀满。心下急痞痛。逆气胁风痛。安胃气。止溏泄。明目。生河内。九月十月采。阴干。</p>\r\n<p>$q{《药性论》}：【枳实】臣。味苦辛。解伤寒结胸。入陷胸汤用。主上气喘咳。肾内伤冷。阴痿而有气。加而用之。</p>\r\n<p>$q{《药性论》}：【枳壳】使。味苦辛。治遍身风疹。肌中如麻豆恶痒。主肠风痔疾。心腹结气。两胁胀虚。关膈壅塞。根浸酒煎。含治齿痛。消痰有气。加而用之。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":14,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '15、$u{枳实} $q{《神农本草经》}：【枳实】味苦。寒。主治大风在皮肤中。如麻豆苦痒。除寒热。热结。止痢。长肌肉。利五藏。益气。轻身。生河内川泽。 $q{《名医别录》}：【枳实】味酸。微寒。无毒。主除胸胁淡癖。逐停水。破结实。消胀满。心下急痞痛。逆气胁风痛。安胃气。止溏泄。明目。生河内。九月十月采。阴干。 $q{《药性论》}：【枳实】臣。味苦辛。解伤寒结胸。入陷胸汤用。主上气喘咳。肾内伤冷。阴痿而有气。加而用之。 $q{《药性论》}：【枳壳】使。味苦辛。治遍身风疹。肌中如麻豆恶痒。主肠风痔疾。心腹结气。两胁胀虚。关膈壅塞。根浸酒煎。含治齿痛。消痰有气。加而用之。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MCBshcFNHhk', 1, '{"title":"16、细辛","description":"<p>16、$u{细辛}</p>\r\n<p>$q{《神农本草经》}：【细辛】味辛。温。主治咳逆。头痛脑动。百节拘挛。风湿痹痛。死肌。久服明目。利九窍。轻身。长年。一名小辛。生华阴山谷。</p>\r\n<p>$q{《名医别录》}：【细辛】无毒。主温中。下气。破痰。利水道。开胸中。除喉痹。齆鼻风痫。癫疾。下乳结。汗不出。血不行。安五藏。益肝胆。通精气。生华阴。二月八月采根。阴干。（曾青桑白皮为之使。反藜芦。恶狼毒山茱萸黄芪。畏滑石消石。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":15,"yaoNames":"小辛","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '16、$u{细辛} $q{《神农本草经》}：【细辛】味辛。温。主治咳逆。头痛脑动。百节拘挛。风湿痹痛。死肌。久服明目。利九窍。轻身。长年。一名小辛。生华阴山谷。 $q{《名医别录》}：【细辛】无毒。主温中。下气。破痰。利水道。开胸中。除喉痹。齆鼻风痫。癫疾。下乳结。汗不出。血不行。安五藏。益肝胆。通精气。生华阴。二月八月采根。阴干。（曾青桑白皮为之使。反藜芦。恶狼毒山茱萸黄芪。畏滑石消石。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JFnirDnffR9', 1, '{"title":"17、当归","description":"<p>17、$u{当归}</p>\r\n<p>$q{《神农本草经》}：【当归】味甘。温。主治咳逆上气。温疟寒热洗洗在皮肤中。妇人漏下绝子。诸恶疮疡。金创。煮饮之。一名干归。生陇西川谷。</p>\r\n<p>$q{《名医别录》}：【当归】味辛。无毒。主温中止痛。除客血内塞。中风痓。汗不出。湿痹。中恶。客气虚冷。补五藏。生肌肉。生陇西。二月八月采根。阴干。（恶䕡茹。畏菖蒲海藻牡蒙。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":16,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '17、$u{当归} $q{《神农本草经》}：【当归】味甘。温。主治咳逆上气。温疟寒热洗洗在皮肤中。妇人漏下绝子。诸恶疮疡。金创。煮饮之。一名干归。生陇西川谷。 $q{《名医别录》}：【当归】味辛。无毒。主温中止痛。除客血内塞。中风痓。汗不出。湿痹。中恶。客气虚冷。补五藏。生肌肉。生陇西。二月八月采根。阴干。（恶䕡茹。畏菖蒲海藻牡蒙。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hs7PKqMqKRj', 1, '{"title":"18、杏仁","description":"<p>18、$u{杏仁}</p>\r\n<p>$q{《神农本草经》}：【杏核】味甘。温。主治咳逆上气。雷鸣。喉痹。下气。产乳。金创。寒心。贲豚。生晋山川谷。</p>\r\n<p>$q{《名医别录》}：【杏核】味苦。冷利。有毒。主治惊痫。心下烦热。风气去来。时行头痛。解肌。消心下急。杀狗毒。一名杏子。五月采。其两仁者杀人。可以毒狗。【花】味苦。无毒。主补不足。女子伤中。寒热痹。厥逆。【实】味酸。不可多食。伤筋骨。生晋山。（得火良。恶黄芪黄芩葛根。解锡毒。畏蘘草。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":17,"yaoNames":"杏核仁","aliases":[{"bieming":"杏子","name":"杏仁"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '18、$u{杏仁} $q{《神农本草经》}：【杏核】味甘。温。主治咳逆上气。雷鸣。喉痹。下气。产乳。金创。寒心。贲豚。生晋山川谷。 $q{《名医别录》}：【杏核】味苦。冷利。有毒。主治惊痫。心下烦热。风气去来。时行头痛。解肌。消心下急。杀狗毒。一名杏子。五月采。其两仁者杀人。可以毒狗。【花】味苦。无毒。主补不足。女子伤中。寒热痹。厥逆。【实】味酸。不可多食。伤筋骨。生晋山。（得火良。恶黄芪黄芩葛根。解锡毒。畏蘘草。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S7mhkBtEhPL', 1, '{"title":"19、石膏","description":"<p>19、$u{石膏}</p>\r\n<p>$q{《神农本草经》}：【石膏】味辛。微寒。主治中风寒热。心下逆气。惊喘。口干舌焦不能息。腹中坚痛。除邪鬼。产乳。金疮。生齐山山谷。</p>\r\n<p>$q{《名医别录》}：【石膏】味甘。大寒。无毒。主除时气。头痛。身热。三焦大热。皮肤热。肠胃中鬲热。解肌。发汗。止消渴。烦逆。腹胀。暴气喘息。咽热。亦可作浴汤。一名细石。细理白泽者者良。黄者令人淋。生齐山及齐卢山鲁蒙山。采无时。（鸡子为之使。恶莽草毒公。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":18,"yaoNames":"寒水石","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '19、$u{石膏} $q{《神农本草经》}：【石膏】味辛。微寒。主治中风寒热。心下逆气。惊喘。口干舌焦不能息。腹中坚痛。除邪鬼。产乳。金疮。生齐山山谷。 $q{《名医别录》}：【石膏】味甘。大寒。无毒。主除时气。头痛。身热。三焦大热。皮肤热。肠胃中鬲热。解肌。发汗。止消渴。烦逆。腹胀。暴气喘息。咽热。亦可作浴汤。一名细石。细理白泽者者良。黄者令人淋。生齐山及齐卢山鲁蒙山。采无时。（鸡子为之使。恶莽草毒公。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8714SID7nWu', 1, '{"title":"20、厚朴","description":"<p>20、$u{厚朴}</p>\r\n<p>$q{《神农本草经》}：【厚朴】味苦。温。主治中风。伤寒。头痛。寒热。惊悸气。血痹。死肌。去三虫。生交趾山谷。</p>\r\n<p>$q{《名医别录》}：【厚朴】大温。无毒。主温中。益气。消痰。下气。治霍乱及腹痛胀满。胃中冷逆。胸中呕逆不止。泄痢。淋露。除惊。去留热。止烦满。厚肠胃。一名厚皮。一名赤朴。其树名榛。子名逐杨。治鼠瘘。明目。益气。生交趾宛朐。三月九月十月采皮。阴干。（干姜为之使。恶泽泻寒水石消石。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":19,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '20、$u{厚朴} $q{《神农本草经》}：【厚朴】味苦。温。主治中风。伤寒。头痛。寒热。惊悸气。血痹。死肌。去三虫。生交趾山谷。 $q{《名医别录》}：【厚朴】大温。无毒。主温中。益气。消痰。下气。治霍乱及腹痛胀满。胃中冷逆。胸中呕逆不止。泄痢。淋露。除惊。去留热。止烦满。厚肠胃。一名厚皮。一名赤朴。其树名榛。子名逐杨。治鼠瘘。明目。益气。生交趾宛朐。三月九月十月采皮。阴干。（干姜为之使。恶泽泻寒水石消石。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sfmcy2PNzjm', 1, '{"title":"21、芎䓖","description":"<p>21、$u{芎䓖}：芎藭</p>\r\n<p>$q{《神农本草经》}：【芎藭】味辛。温。主治中风入脑头痛。寒痹。筋挛缓急。金疮。妇人血闭无子。生武功川谷。</p>\r\n<p>$q{《名医别录》}：【芎藭】无毒。主除脑中冷动。面上游风去来。目泪出。多涕唾。忽忽如醉。诸寒冷气。心腹坚痛。中恶。卒急肿痛。胁风痛。温中内寒。一名胡穷。一名香果。其叶名蘼芜。生武功斜谷西岭。三月四月采根。暴干。（白芷为之使。恶黄连。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":20,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '21、$u{芎䓖}：芎藭 $q{《神农本草经》}：【芎藭】味辛。温。主治中风入脑头痛。寒痹。筋挛缓急。金疮。妇人血闭无子。生武功川谷。 $q{《名医别录》}：【芎藭】无毒。主除脑中冷动。面上游风去来。目泪出。多涕唾。忽忽如醉。诸寒冷气。心腹坚痛。中恶。卒急肿痛。胁风痛。温中内寒。一名胡穷。一名香果。其叶名蘼芜。生武功斜谷西岭。三月四月采根。暴干。（白芷为之使。恶黄连。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T3B7gaA2R03', 1, '{"title":"22、阿胶","description":"<p>22、$u{阿胶}</p>\r\n<p>$q{《神农本草经》}：【阿胶】味甘。平。主治心腹内崩。劳极洒洒如疟状。腰腹痛。四肢酸疼。女子下血。安胎。久服轻身。益气。一名傅致胶。生东阿。</p>\r\n<p>$q{《名医别录》}：【阿胶】微温。无毒。主丈夫少腹痛。虚劳羸瘦。阴气不足。脚酸不能久立。养肝气。生东平郡。煮牛皮作之。出东阿。（恶大黄。得火良。）</p>\r\n<p>$q{《名医别录》}：【白胶】温。无毒。主治吐血。下血。崩中不止。四肢酸疼。多汗。淋露。折跌伤损。生云中。煮鹿角作之。（得火良。畏大黄。）</p>\r\n<p>$q{《药性论》}：【阿胶】君。主坚筋骨。益气。止痢。署预为之使。</p>\r\n<p>$q{《药性论》}：【白胶】又名黄明胶。能主男子肾藏气衰虚劳损。妇人服之。令有子。能安胎去冷。治漏下赤白。主吐血。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":21,"yaoNames":"傅致胶","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '22、$u{阿胶} $q{《神农本草经》}：【阿胶】味甘。平。主治心腹内崩。劳极洒洒如疟状。腰腹痛。四肢酸疼。女子下血。安胎。久服轻身。益气。一名傅致胶。生东阿。 $q{《名医别录》}：【阿胶】微温。无毒。主丈夫少腹痛。虚劳羸瘦。阴气不足。脚酸不能久立。养肝气。生东平郡。煮牛皮作之。出东阿。（恶大黄。得火良。） $q{《名医别录》}：【白胶】温。无毒。主治吐血。下血。崩中不止。四肢酸疼。多汗。淋露。折跌伤损。生云中。煮鹿角作之。（得火良。畏大黄。） $q{《药性论》}：【阿胶】君。主坚筋骨。益气。止痢。署预为之使。 $q{《药性论》}：【白胶】又名黄明胶。能主男子肾藏气衰虚劳损。妇人服之。令有子。能安胎去冷。治漏下赤白。主吐血。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C74sm5pJRdN', 1, '{"title":"23、五味子","description":"<p>23、$u{五味子}</p>\r\n<p>$q{《神农本草经》}：【五味子】味酸。温。主益气。咳逆上气。劳伤羸瘦。补不足。强阴。益男子精。生齐山山谷。</p>\r\n<p>$q{《名医别录》}：【五味子】无毒。主养五藏。除热。生阴中肌。一名会及。一名玄及。生齐山及代郡。八月采实。阴干。（苁蓉为之使。恶葳蕤。胜乌头。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":22,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '23、$u{五味子} $q{《神农本草经》}：【五味子】味酸。温。主益气。咳逆上气。劳伤羸瘦。补不足。强阴。益男子精。生齐山山谷。 $q{《名医别录》}：【五味子】无毒。主养五藏。除热。生阴中肌。一名会及。一名玄及。生齐山及代郡。八月采实。阴干。（苁蓉为之使。恶葳蕤。胜乌头。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MDfiJ4S7u0U', 1, '{"title":"24、牡蛎","description":"<p>24、$u{牡蛎}</p>\r\n<p>$q{《神农本草经》}：【牡蛎】味咸。平。主治伤寒寒热。温疟洒洒。惊恚怒气。除拘缓。鼠瘘。女子带下赤白。久服强骨节。杀邪鬼。延年。一名蛎蛤。生东海池泽。</p>\r\n<p>$q{《名医别录》}：【牡蛎】微寒。无毒。主除留热在关节荣卫。虚热去来不定。烦满。止汗。心痛气结。止渴。除老血。涩大小肠。止大小便。治泄精喉痹咳嗽心胁下痞热。一名牡蛤。生东海。采时。（贝母为之使。得甘草牛膝远志蛇床良。恶麻黄吴茱萸辛夷。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":23,"yaoNames":"蛎蛤","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '24、$u{牡蛎} $q{《神农本草经》}：【牡蛎】味咸。平。主治伤寒寒热。温疟洒洒。惊恚怒气。除拘缓。鼠瘘。女子带下赤白。久服强骨节。杀邪鬼。延年。一名蛎蛤。生东海池泽。 $q{《名医别录》}：【牡蛎】微寒。无毒。主除留热在关节荣卫。虚热去来不定。烦满。止汗。心痛气结。止渴。除老血。涩大小肠。止大小便。治泄精喉痹咳嗽心胁下痞热。一名牡蛤。生东海。采时。（贝母为之使。得甘草牛膝远志蛇床良。恶麻黄吴茱萸辛夷。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JMpy06saY9b', 1, '{"title":"25、酒","description":"<p>25、$u{酒}（白酒、清酒、美清酒、醇酒）</p>\r\n<p>$q{《名医别录》}：【酒】味苦甘辛。大热。有毒。主行药势。杀邪恶气。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":24,"yaoNames":"","aliases":[{"bieming":"清酒","name":"酒"},{"bieming":"白酒","name":"酒"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '25、$u{酒}（白酒、清酒、美清酒、醇酒） $q{《名医别录》}：【酒】味苦甘辛。大热。有毒。主行药势。杀邪恶气。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i7j1zMcc48a', 1, '{"title":"26、黄芪","description":"<p>26、$u{黄芪}</p>\r\n<p>$q{《神农本草经》}：【黄耆】味甘。微温。主治痈疽。久败疮。排脓止痛。大风癞疾。五痔。鼠瘘。补虚。小儿百病。一名戴糁。生蜀郡山谷。</p>\r\n<p>$q{《名医别录》}：【黄耆】无毒。主治妇人子藏风邪气。逐五藏间恶血。补丈夫虚损。五劳羸瘦。止渴。腹痛泄利。益气。利阴气。生白水者冷。补。其【茎叶】治渴及筋挛。痈肿。疽疮。一名戴椹。一名独椹。一名芰草。一名蜀脂。一名百本。生蜀郡白水汉中。二月十月采。阴干。（恶龟甲。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":25,"yaoNames":"黄耆","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '26、$u{黄芪} $q{《神农本草经》}：【黄耆】味甘。微温。主治痈疽。久败疮。排脓止痛。大风癞疾。五痔。鼠瘘。补虚。小儿百病。一名戴糁。生蜀郡山谷。 $q{《名医别录》}：【黄耆】无毒。主治妇人子藏风邪气。逐五藏间恶血。补丈夫虚损。五劳羸瘦。止渴。腹痛泄利。益气。利阴气。生白水者冷。补。其【茎叶】治渴及筋挛。痈肿。疽疮。一名戴椹。一名独椹。一名芰草。一名蜀脂。一名百本。生蜀郡白水汉中。二月十月采。阴干。（恶龟甲。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B2o1hdSD6X1', 1, '{"title":"27、地黄","description":"<p>27、$u{地黄}（干地黄、生地黄、地黄汁、生地黄汁）</p>\r\n<p>$q{《神农本草经》}：【干地黄】味甘。寒。主治折跌。绝筋。伤中。逐血痹。填骨髓。长肌肉。作汤除寒热积聚。除痹。生者尤良。久服轻身。不老。一名地髓。生咸阳川泽。</p>\r\n<p>$q{《名医别录》}：【干地黄】味苦。无毒。主治男子五劳七伤。女子伤中胞漏下血。破恶血溺血。利大小肠。去胃中宿食。饱力断绝。补五藏内伤不足。通血脉。益气力。利耳目。</p>\r\n<p>$q{《名医别录》}：【生地黄】大寒。主治妇人崩中血不止。及产后血上薄心闷绝。伤身胎动下血。胎不落。堕坠。踠折。瘀血。留血。衄鼻。吐血。皆捣饮之。一名芐。一名芑。一名地脉。生咸阳黄土地者佳。二月八月采根。阴干。（得麦门冬清酒良。恶贝母。畏芜荑。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":26,"yaoNames":"干地黄、生地黄、地黄汁、生地黄汁","aliases":[{"bieming":"生地黄","name":"地黄"},{"bieming":"干地黄","name":"地黄"},{"bieming":"生地","name":"地黄"},{"bieming":"熟地","name":"地黄"},{"bieming":"生地黄汁","name":"地黄"},{"bieming":"地黄汁","name":"地黄"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '27、$u{地黄}（干地黄、生地黄、地黄汁、生地黄汁） $q{《神农本草经》}：【干地黄】味甘。寒。主治折跌。绝筋。伤中。逐血痹。填骨髓。长肌肉。作汤除寒热积聚。除痹。生者尤良。久服轻身。不老。一名地髓。生咸阳川泽。 $q{《名医别录》}：【干地黄】味苦。无毒。主治男子五劳七伤。女子伤中胞漏下血。破恶血溺血。利大小肠。去胃中宿食。饱力断绝。补五藏内伤不足。通血脉。益气力。利耳目。 $q{《名医别录》}：【生地黄】大寒。主治妇人崩中血不止。及产后血上薄心闷绝。伤身胎动下血。胎不落。堕坠。踠折。瘀血。留血。衄鼻。吐血。皆捣饮之。一名芐。一名芑。一名地脉。生咸阳黄土地者佳。二月八月采根。阴干。（得麦门冬清酒良。恶贝母。畏芜荑。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JMfcgoRTH0J', 1, '{"title":"28、柴胡","description":"<p>28、$u{柴胡}</p>\r\n<p>$q{《神农本草经》}：【茈胡】味苦。平。主治心腹。去肠胃中结气。饮食积聚。寒热邪气。推陈致新。久服轻身。明目。益精。一名地薰。生弘农川谷。</p>\r\n<p>$q{《名医别录》}：【茈胡】微寒。无毒。主除伤寒。心下烦热。诸痰热结实。胸中邪逆。五藏间游气。大肠停积水胀。及湿痹拘挛。亦可作浴汤。一名山菜。一名茹草。【叶】一名芸蒿。辛香可食。生洪农及宛朐。二月八月采根。暴干。（得茯苓桔梗大黄石膏麻子仁甘草桂。以水一斗煮。取四升。入消石三方寸匕。治伤寒寒热头痛心下烦满。半夏为之使。恶皂荚。畏女菀藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":27,"yaoNames":"地薰,茈胡","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '28、$u{柴胡} $q{《神农本草经》}：【茈胡】味苦。平。主治心腹。去肠胃中结气。饮食积聚。寒热邪气。推陈致新。久服轻身。明目。益精。一名地薰。生弘农川谷。 $q{《名医别录》}：【茈胡】微寒。无毒。主除伤寒。心下烦热。诸痰热结实。胸中邪逆。五藏间游气。大肠停积水胀。及湿痹拘挛。亦可作浴汤。一名山菜。一名茹草。【叶】一名芸蒿。辛香可食。生洪农及宛朐。二月八月采根。暴干。（得茯苓桔梗大黄石膏麻子仁甘草桂。以水一斗煮。取四升。入消石三方寸匕。治伤寒寒热头痛心下烦满。半夏为之使。恶皂荚。畏女菀藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5GP5Zyu6577', 1, '{"title":"29、黄连","description":"<p>29、$u{黄连}</p>\r\n<p>$q{《神农本草经》}：【黄连】味苦。寒。主治热气。目痛。眦伤。泣出。明目。肠澼。腹痛。下痢。妇人阴中肿痛。久服令人不忘。一名王连。生巫阳川谷。</p>\r\n<p>$q{《名医别录》}：【黄连】微寒。无毒。主治五藏冷热。久下泄澼脓血。止消渴大惊。除水。利骨。调胃。厚肠。益胆。治口疮。生巫阳及蜀郡太山。二月八月采。（黄芩龙骨理石为之使。恶菊花芫花玄参白鲜。畏款冬。胜乌头。解巴豆毒。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":28,"yaoNames":"王连","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '29、$u{黄连} $q{《神农本草经》}：【黄连】味苦。寒。主治热气。目痛。眦伤。泣出。明目。肠澼。腹痛。下痢。妇人阴中肿痛。久服令人不忘。一名王连。生巫阳川谷。 $q{《名医别录》}：【黄连】微寒。无毒。主治五藏冷热。久下泄澼脓血。止消渴大惊。除水。利骨。调胃。厚肠。益胆。治口疮。生巫阳及蜀郡太山。二月八月采。（黄芩龙骨理石为之使。恶菊花芫花玄参白鲜。畏款冬。胜乌头。解巴豆毒。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t7DkIvGNO8b', 1, '{"title":"30、桔梗","description":"<p>30、$u{桔梗}</p>\r\n<p>$q{《神农本草经》}：【桔梗】味辛。微温。主治胸胁痛如刀刺。腹满。肠鸣幽幽。惊恐悸气。生嵩高山谷。</p>\r\n<p>$q{《名医别录》}：【桔梗】味苦。有小毒。主利五藏肠胃。补血气。除寒热风痹。温中。消谷。治喉咽痛。下蛊毒。一名利如。一名房图。一名白药。一名梗草。一名荠苨。生嵩高及宛朐。二八月采根。暴干。（节皮为之使。得牡蛎远志治恚怒。得消石石膏治伤寒。畏白及龙眼龙胆。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":29,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '30、$u{桔梗} $q{《神农本草经》}：【桔梗】味辛。微温。主治胸胁痛如刀刺。腹满。肠鸣幽幽。惊恐悸气。生嵩高山谷。 $q{《名医别录》}：【桔梗】味苦。有小毒。主利五藏肠胃。补血气。除寒热风痹。温中。消谷。治喉咽痛。下蛊毒。一名利如。一名房图。一名白药。一名梗草。一名荠苨。生嵩高及宛朐。二八月采根。暴干。（节皮为之使。得牡蛎远志治恚怒。得消石石膏治伤寒。畏白及龙眼龙胆。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k2cI79Wat6h', 1, '{"title":"31、桃仁","description":"<p>31、$u{桃仁}</p>\r\n<p>$q{《神农本草经》}：【桃核】味苦。平。主治瘀血。血闭瘕邪气。杀小虫。</p>\r\n<p>$q{《名医别录》}：【桃核】味甘。无毒。主咳逆上气。消心下坚。除卒暴击血。破癥瘕。通月水。止痛。七月采取仁。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":30,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '31、$u{桃仁} $q{《神农本草经》}：【桃核】味苦。平。主治瘀血。血闭瘕邪气。杀小虫。 $q{《名医别录》}：【桃核】味甘。无毒。主咳逆上气。消心下坚。除卒暴击血。破癥瘕。通月水。止痛。七月采取仁。阴干。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TvTXZli2dE7', 1, '{"title":"32、泽泻","description":"<p>32、$u{泽泻}</p>\r\n<p>$q{《神农本草经》}：【泽泻】味甘。寒。主治风寒湿痹。乳难。消水。养五藏。益气力。肥健。久服耳目聪明。不饥。延年。轻身。面生光。能行水上。一名水泻。一名芒芋。一名鹄泻。生汝南池泽。</p>\r\n<p>$q{《名医别录》}：【泽泻】味咸。无毒。主补虚损五劳。除五藏痞满。起阴气。止泄精消渴淋沥。逐膀胱三焦停水。扁鹊云多服病人眼。一名及泻。生汝南。五月六月八月采根。阴干。（畏海蛤文蛤。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":31,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '32、$u{泽泻} $q{《神农本草经》}：【泽泻】味甘。寒。主治风寒湿痹。乳难。消水。养五藏。益气力。肥健。久服耳目聪明。不饥。延年。轻身。面生光。能行水上。一名水泻。一名芒芋。一名鹄泻。生汝南池泽。 $q{《名医别录》}：【泽泻】味咸。无毒。主补虚损五劳。除五藏痞满。起阴气。止泄精消渴淋沥。逐膀胱三焦停水。扁鹊云多服病人眼。一名及泻。生汝南。五月六月八月采根。阴干。（畏海蛤文蛤。）', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4lJokf6uHXR', 1, '{"title":"33、百合","description":"<p>33、$u{百合}</p>\r\n<p>$q{《神农本草经》}：【百合】味甘。平。主治邪气腹胀。心痛。利大小便。补中益气。生荆州川谷。</p>\r\n<p>$q{《名医别录》}：【百合】无毒。主除浮肿。胪胀。痞满。寒热。通身疼痛。及乳难喉痹肿。止涕泪。一名重葙。一名重迈。一名摩罗。一名中逢花。一名强瞿。生荆州。二月八月采根。暴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":32,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '33、$u{百合} $q{《神农本草经》}：【百合】味甘。平。主治邪气腹胀。心痛。利大小便。补中益气。生荆州川谷。 $q{《名医别录》}：【百合】无毒。主除浮肿。胪胀。痞满。寒热。通身疼痛。及乳难喉痹肿。止涕泪。一名重葙。一名重迈。一名摩罗。一名中逢花。一名强瞿。生荆州。二月八月采根。暴干。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IHSagd4ikNY', 1, '{"title":"34、石蜜","description":"<p>34、$u{蜜}（白蜜）</p>\n<p>$q{《神农本草经》}：【石蜜】味甘。平。主治心腹邪气。诸惊痫痓。安五藏。诸不足。益气。补中。止痛。解毒。除众病。和百药。久服强志。轻身。不饥。不老。一名石饴。生武都山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【石蜜】微温。无毒。主养脾气。除心烦。食饮不下。止肠澼。肌中疼痛。口疮。明耳目。久服延年神仙。生武都河源山谷及诸山石中。色白如膏者良。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":33,"yaoNames":"白蜜,蜜","aliases":[{"bieming":"白蜜","name":"蜜"},{"bieming":"食蜜","name":"蜜"}],"volume":"中药"}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '34、$u{蜜}（白蜜） $q{《神农本草经》}：【石蜜】味甘。平。主治心腹邪气。诸惊痫痓。安五藏。诸不足。益气。补中。止痛。解毒。除众病。和百药。久服强志。轻身。不饥。不老。一名石饴。生武都山谷。 $q{《名医别录》}：【石蜜】微温。无毒。主养脾气。除心烦。食饮不下。止肠澼。肌中疼痛。口疮。明耳目。久服延年神仙。生武都河源山谷及诸山石中。色白如膏者良。', '2024-09-14T16:56:57.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M9HezPeSGkC', 1, '{"title":"35、防己","description":"<p>35、$u{防己}（木防己）</p>\r\n<p>$q{《神农本草经》}：【防己】味辛。平。主治风寒。温疟。热气。诸痫。除邪。利大小便。一名解离。生汉中川谷。</p>\r\n<p>$q{《名医别录》}：【防己】味苦。温。无毒。主治水肿。风肿。去膀胱热。伤寒。寒热邪气。中风。手脚挛急。止泄。散痈肿恶结。诸蜗疥癣。虫疮。通腠理。利九窍。文如车辐理解者良。生汉中。二月八月采根。阴干。（殷孽为之使。杀雄黄毒。恶细辛。畏萆薢。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":34,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '35、$u{防己}（木防己） $q{《神农本草经》}：【防己】味辛。平。主治风寒。温疟。热气。诸痫。除邪。利大小便。一名解离。生汉中川谷。 $q{《名医别录》}：【防己】味苦。温。无毒。主治水肿。风肿。去膀胱热。伤寒。寒热邪气。中风。手脚挛急。止泄。散痈肿恶结。诸蜗疥癣。虫疮。通腠理。利九窍。文如车辐理解者良。生汉中。二月八月采根。阴干。（殷孽为之使。杀雄黄毒。恶细辛。畏萆薢。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u6WaDjpcWhR', 1, '{"title":"36、滑石","description":"<p>36、$u{滑石}</p>\r\n<p>$q{《神农本草经》}：【滑石】味甘。寒。主治身热。泄澼。女子乳难。癃闭。利小便。荡胃中积聚寒热。益精气。久服轻身。耐饥。长年。生赭阳山谷。</p>\r\n<p>$q{《名医别录》}：【滑石】大寒。无毒。通九窍六府津液。去留结。止渴。令人利中。一名液石。一名共石。一名脆石。一名番石。生赭阳及太山之阴或掖北白山或卷山。采无时。（石韦为之使。恶曾青。）</p>\r\n<p>$q{《药性论》}∶【滑石】臣。一名夕冷。能疗五淋。主难产。服其末。又末与丹参蜜猪脂为膏。入其月。即空心酒下弹丸大。临产倍服。令滑胎易生。除烦热心躁。偏主石淋。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":35,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '36、$u{滑石} $q{《神农本草经》}：【滑石】味甘。寒。主治身热。泄澼。女子乳难。癃闭。利小便。荡胃中积聚寒热。益精气。久服轻身。耐饥。长年。生赭阳山谷。 $q{《名医别录》}：【滑石】大寒。无毒。通九窍六府津液。去留结。止渴。令人利中。一名液石。一名共石。一名脆石。一名番石。生赭阳及太山之阴或掖北白山或卷山。采无时。（石韦为之使。恶曾青。） $q{《药性论》}∶【滑石】臣。一名夕冷。能疗五淋。主难产。服其末。又末与丹参蜜猪脂为膏。入其月。即空心酒下弹丸大。临产倍服。令滑胎易生。除烦热心躁。偏主石淋。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nP2w4ZP4Yic', 1, '{"title":"37、牡丹皮","description":"<p>37、$u{牡丹皮}</p>\r\n<p>$q{《神农本草经》}：【牡丹】味辛。寒。主治寒热。中风。瘛疭。痉。惊痫。邪气。除癥坚。瘀血留舍肠胃。安五藏。治痈疮。一名鹿韭。一名鼠姑。生巴郡山谷。</p>\r\n<p>$q{《名医别录》}：【牡丹】味苦。微寒。无毒。主除时气。头痛。客热。五劳。劳气。头腰痛。风噤。癫疾。生巴郡及汉中。二月八月采根。阴干。（畏菟丝子。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":36,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '37、$u{牡丹皮} $q{《神农本草经》}：【牡丹】味辛。寒。主治寒热。中风。瘛疭。痉。惊痫。邪气。除癥坚。瘀血留舍肠胃。安五藏。治痈疮。一名鹿韭。一名鼠姑。生巴郡山谷。 $q{《名医别录》}：【牡丹】味苦。微寒。无毒。主除时气。头痛。客热。五劳。劳气。头腰痛。风噤。癫疾。生巴郡及汉中。二月八月采根。阴干。（畏菟丝子。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('03dIYYkyQRn', 1, '{"title":"38、蜀椒","description":"<p>38、$u{蜀椒}</p>\r\n<p>$q{《神农本草经》}：【蜀椒】味辛。温。主治邪气咳逆。温中。逐骨节皮肤死肌。寒湿痹痛。下气。久服之头不白。轻身。增年。生武都川谷。</p>\r\n<p>$q{《名医别录》}：【蜀椒】大热。有毒。主除五藏六府寒冷。伤寒。温疟。大风。汗不出。心腹留饮宿食。止肠澼下利。泄精。女子字乳余疾。散风邪。瘕结。水肿。黄疸。鬼疰。蛊毒。杀虫鱼毒。久服开腠理。通血脉。坚齿发。调关节。耐寒暑。可作膏药。多食令人乏气。口闭者杀人。一名巴椒。一名蓎藙。生武都及巴郡。八月采实。阴干。（杏仁为之使。畏槖吾。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":37,"yaoNames":"川椒","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '38、$u{蜀椒} $q{《神农本草经》}：【蜀椒】味辛。温。主治邪气咳逆。温中。逐骨节皮肤死肌。寒湿痹痛。下气。久服之头不白。轻身。增年。生武都川谷。 $q{《名医别录》}：【蜀椒】大热。有毒。主除五藏六府寒冷。伤寒。温疟。大风。汗不出。心腹留饮宿食。止肠澼下利。泄精。女子字乳余疾。散风邪。瘕结。水肿。黄疸。鬼疰。蛊毒。杀虫鱼毒。久服开腠理。通血脉。坚齿发。调关节。耐寒暑。可作膏药。多食令人乏气。口闭者杀人。一名巴椒。一名蓎藙。生武都及巴郡。八月采实。阴干。（杏仁为之使。畏槖吾。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pyZLleBsXOb', 1, '{"title":"39、栝蒌根","description":"<p>39、$u{栝楼根}</p>\r\n<p>$q{《神农本草经》}：【栝楼】味苦。寒。主治消渴。身热烦满。大热。补虚。安中。续绝伤。一名地楼。生弘农川谷。</p>\r\n<p>$q{《名医别录》}：【栝楼根】无毒。主除肠胃中痼热。八疸。身面黄。唇干口燥。短气。通月水。止小便利。一名果裸。一名天瓜。一名泽姑。生洪农及山阴地。入土深者良。生卤地者有毒。二月八月采根。暴干。三十日成。（枸杞为之使。恶干姜。畏牛膝干漆。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":38,"yaoNames":"瓜蒌根,栝楼根,括蒌根","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '39、$u{栝楼根} $q{《神农本草经》}：【栝楼】味苦。寒。主治消渴。身热烦满。大热。补虚。安中。续绝伤。一名地楼。生弘农川谷。 $q{《名医别录》}：【栝楼根】无毒。主除肠胃中痼热。八疸。身面黄。唇干口燥。短气。通月水。止小便利。一名果裸。一名天瓜。一名泽姑。生洪农及山阴地。入土深者良。生卤地者有毒。二月八月采根。暴干。三十日成。（枸杞为之使。恶干姜。畏牛膝干漆。反乌头。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2gRWUBY7CiY', 1, '{"title":"40、粳米","description":"<p>40、$u{粳米}</p>\r\n<p>$q{《名医别录》}：【粳米】味甘苦。平。无毒。主益气。止烦。止泄。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":39,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '40、$u{粳米} $q{《名医别录》}：【粳米】味甘苦。平。无毒。主益气。止烦。止泄。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PeV28d5T6et', 1, '{"title":"41、知母","description":"<p>41、$u{知母}</p>\r\n<p>$q{《神农本草经》}：【知母】味苦。寒。主治消渴热中。除邪气。肢体浮肿。下水。补不足。益气。一名蚳母。一名连母。一名野蓼。一名地参。一名水参。一名水浚。一名货母。一名蝭母。生河内川谷。</p>\r\n<p>$q{《名医别录》}：【知母】无毒。主治伤寒久疟烦热。胁下邪气。膈中恶。及风汗内疸。多服令人泄。一名女雷。一名女理。一名儿草。一名鹿列。一名韭逢。一名儿踵草。一名东根。一名水须。一名沈燔。一名薅。生河内。二月八月采根。暴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":40,"yaoNames":"蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '41、$u{知母} $q{《神农本草经》}：【知母】味苦。寒。主治消渴热中。除邪气。肢体浮肿。下水。补不足。益气。一名蚳母。一名连母。一名野蓼。一名地参。一名水参。一名水浚。一名货母。一名蝭母。生河内川谷。 $q{《名医别录》}：【知母】无毒。主治伤寒久疟烦热。胁下邪气。膈中恶。及风汗内疸。多服令人泄。一名女雷。一名女理。一名儿草。一名鹿列。一名韭逢。一名儿踵草。一名东根。一名水须。一名沈燔。一名薅。生河内。二月八月采根。暴干。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KIP0kUQVkZG', 1, '{"title":"42、猪胆","description":"<p>42、$u{猪胆汁}（猪胆）[$q{《伤寒论》}有“无猪胆。以羊胆代之”语，故附青羊胆。]</p>\r\n<p>$q{《名医别录》}：【猪胆】治伤寒热渴。</p>\r\n<p>$q{《名医别录》}：【青羊胆】治青盲。明目。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":41,"yaoNames":"猪胆汁,大猪胆汁,大猪胆","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '42、$u{猪胆汁}（猪胆）[$q{《伤寒论》}有“无猪胆。以羊胆代之”语，故附青羊胆。] $q{《名医别录》}：【猪胆】治伤寒热渴。 $q{《名医别录》}：【青羊胆】治青盲。明目。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('blvt71sB8Zu', 1, '{"title":"43、防风","description":"<p>43、$u{防风}</p>\r\n<p>$q{《神农本草经》}：【防风】味甘。温。主治大风头眩痛。恶风。风邪。目盲无所见。风行周身。骨节疼痹。烦满。久服轻身。一名铜芸。生沙苑川泽。</p>\r\n<p>$q{《名医别录》}：【防风】味辛。无毒。主治胁痛胁风头面去来。四肢挛急。字乳金疮内痉。一名茴草。一名百枝。一名屏风。一名䕡根。一名百蜚。生沙苑及邯郸琅邪上蔡。二月十月采根。暴干。（得泽泻藁本治风。得当归芍药阳起石禹余粮治妇人子藏风。恶干姜藜芦白蔹芫花。杀附子毒。）又。叉头者令人发狂。叉尾者发痼疾。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":42,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '43、$u{防风} $q{《神农本草经》}：【防风】味甘。温。主治大风头眩痛。恶风。风邪。目盲无所见。风行周身。骨节疼痹。烦满。久服轻身。一名铜芸。生沙苑川泽。 $q{《名医别录》}：【防风】味辛。无毒。主治胁痛胁风头面去来。四肢挛急。字乳金疮内痉。一名茴草。一名百枝。一名屏风。一名䕡根。一名百蜚。生沙苑及邯郸琅邪上蔡。二月十月采根。暴干。（得泽泻藁本治风。得当归芍药阳起石禹余粮治妇人子藏风。恶干姜藜芦白蔹芫花。杀附子毒。）又。叉头者令人发狂。叉尾者发痼疾。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dFbCWGnQmeQ', 1, '{"title":"44、乌头","description":"<p>44、$u{乌头}</p>\r\n<p>$q{《神农本草经》}：【乌头】味辛。温。主治中风。恶风洗洗。出汗。除寒湿痹。咳逆上气。破积聚。寒热。其汁煎之名射罔。杀禽兽。一名奚毒。一名即子。一名乌喙。生朗陵川谷。</p>\r\n<p>$q{《名医别录》}：【乌头】味甘。大热。有毒。消胸上淡冷。食不下。心腹冷疾。脐间痛。肩胛痛不可俯仰。目中痛不可力视。又堕胎。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":43,"yaoNames":"","aliases":[{"bieming":"川乌","name":"乌头"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '44、$u{乌头} $q{《神农本草经》}：【乌头】味辛。温。主治中风。恶风洗洗。出汗。除寒湿痹。咳逆上气。破积聚。寒热。其汁煎之名射罔。杀禽兽。一名奚毒。一名即子。一名乌喙。生朗陵川谷。 $q{《名医别录》}：【乌头】味甘。大热。有毒。消胸上淡冷。食不下。心腹冷疾。脐间痛。肩胛痛不可俯仰。目中痛不可力视。又堕胎。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vL3tFGA7NwL', 1, '{"title":"45、龙骨","description":"<p>45、$u{龙骨}</p>\r\n<p>$q{《神农本草经》}：【龙骨】味甘。平。无毒。主治心腹鬼疰。精物。老魅。咳逆。泄痢脓血。女子漏下。癥瘕坚结。小儿热气惊痫。</p>\r\n<p>$q{《名医别录》}：【龙骨】微寒。无毒。主治心腹烦满。四肢痿枯。汗出。夜卧自惊。恚怒。伏气在心下。不得喘息。肠痈内疽阴蚀。止汗。小便利。溺血。养精神。定魂魄。安五藏。</p>\r\n<p>$q{《名医别录》}：【白龙骨】治梦寐泄精。小便泄精。</p>\r\n<p>$q{《药性论》}：【龙骨】君。忌鱼。有小毒。逐邪气。安心神。止冷痢及下脓血。女子崩中带下。止梦泄精。夜梦鬼交。治尿血。虚而多梦纷纭者加而用之。</p>\r\n<p>$q{《神农本草经》}：【龙齿】主治小儿大人惊痫。癫疾狂走。心下结气。不能喘息。诸痉。杀精物。久服轻身。通神明。延年。生晋地川谷。</p>\r\n<p>$q{《名医别录》}：【龙齿】主治小儿五惊。十二痫。身热不可近人。大人骨间寒热。又杀蛊毒。【角】主治惊痫瘛疭。身热如火。腹中坚及热泄。生晋地及太山岩水岸土穴石中死龙处。采无时。（龙骨。得人参牛黄良。畏石膏龙角。畏干漆蜀椒理石。）</p>\r\n<p>$q{《药性论》}：【龙齿】君。镇心。安魂魄。齿角俱主小儿大热。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":44,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '45、$u{龙骨} $q{《神农本草经》}：【龙骨】味甘。平。无毒。主治心腹鬼疰。精物。老魅。咳逆。泄痢脓血。女子漏下。癥瘕坚结。小儿热气惊痫。 $q{《名医别录》}：【龙骨】微寒。无毒。主治心腹烦满。四肢痿枯。汗出。夜卧自惊。恚怒。伏气在心下。不得喘息。肠痈内疽阴蚀。止汗。小便利。溺血。养精神。定魂魄。安五藏。 $q{《名医别录》}：【白龙骨】治梦寐泄精。小便泄精。 $q{《药性论》}：【龙骨】君。忌鱼。有小毒。逐邪气。安心神。止冷痢及下脓血。女子崩中带下。止梦泄精。夜梦鬼交。治尿血。虚而多梦纷纭者加而用之。 $q{《神农本草经》}：【龙齿】主治小儿大人惊痫。癫疾狂走。心下结气。不能喘息。诸痉。杀精物。久服轻身。通神明。延年。生晋地川谷。 $q{《名医别录》}：【龙齿】主治小儿五惊。十二痫。身热不可近人。大人骨间寒热。又杀蛊毒。【角】主治惊痫瘛疭。身热如火。腹中坚及热泄。生晋地及太山岩水岸土穴石中死龙处。采无时。（龙骨。得人参牛黄良。畏石膏龙角。畏干漆蜀椒理石。） $q{《药性论》}：【龙齿】君。镇心。安魂魄。齿角俱主小儿大热。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('216GW1qIoXb', 1, '{"title":"46、橘皮","description":"<p>46、$u{橘皮}</p>\r\n<p>$q{《神农本草经》}：【橘柚】味辛。温。主治胸中瘕热气。利水谷。久服去臭。下气通神。一名橘皮。生南山川谷。</p>\r\n<p>$q{《名医别录》}：【橘柚】无毒。主下气。止呕咳。除膀胱留热。下停水。五淋。利小便。治脾不能消谷。气冲胸中。吐逆。霍乱。止泄。去寸白。久服轻身长年。生南山。生江南。十月采。</p>\r\n<p>$q{《药性论》}：【橘皮】臣。味苦辛。能治胸膈间气。开胃。主气利。消痰涎。治上气咳嗽。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":45,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '46、$u{橘皮} $q{《神农本草经》}：【橘柚】味辛。温。主治胸中瘕热气。利水谷。久服去臭。下气通神。一名橘皮。生南山川谷。 $q{《名医别录》}：【橘柚】无毒。主下气。止呕咳。除膀胱留热。下停水。五淋。利小便。治脾不能消谷。气冲胸中。吐逆。霍乱。止泄。去寸白。久服轻身长年。生南山。生江南。十月采。 $q{《药性论》}：【橘皮】臣。味苦辛。能治胸膈间气。开胃。主气利。消痰涎。治上气咳嗽。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J7mL6gla0C0', 1, '{"title":"47、芒硝","description":"<p>47、$u{芒硝}：芒消</p>\r\n<p>$q{《神农本草经》}：【朴消】味苦。寒。主治百病。除寒热邪气。逐六府积聚。结固留癖。能化七十二种石。炼饵服之。轻身。神仙。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【朴消】味辛。大寒。无毒。主治胃中食饮热结。破留血闭绝。停痰痞满。推陈致新。炼之白如银。能寒能热能滑能涩。能辛能苦能咸能酸。入地千岁不变。色青白者佳。黄者伤人。赤者杀人。一名消石朴。生益州有咸水之阳。采无时。（畏麦句姜。）</p>\r\n<p>$q{《神农本草经》}：【消石】味苦寒。主治五藏积热。胃胀闭。涤去蓄结饮食。推陈致新。除邪气。炼之如膏。久服轻身。一名芒消。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【消石】味辛。大寒。无毒。主治五藏十二经脉中百二十疾。暴伤寒腹中大热。止烦满消渴。利小便及瘘蚀疮。天地至神之物。能化成十二种石。生益州。及武都陇西西羌。采无时。（萤火为之使。恶苦参苦菜。畏女菀。）</p>\r\n<p>$q{《名医别录》}：【芒消】味辛苦。大寒。主治五藏积聚。久热胃闭。除邪气。破留血腹中淡实结搏。通脉。利大小便及月水。破五淋。推陈致新。生于朴消。（石韦为之使。畏麦句姜。）</p>\r\n<p>$q{《药性论》}：【芒消】使。味咸，有小毒。能通女子月闭。癥瘕。下瘰疬，黄疸病。主堕胎。患漆疮。汁傅之。主时疾壅热。能散恶血。</p>\r\n<p>$q{《药性论》}：【玄明粉】味辛甘。性冷。无毒。治心热烦躁。并五藏宿滞癥结。明目。退膈上虚热。消肿毒。此即朴消炼成者。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":46,"yaoNames":"朴硝,芒消","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '47、$u{芒硝}：芒消 $q{《神农本草经》}：【朴消】味苦。寒。主治百病。除寒热邪气。逐六府积聚。结固留癖。能化七十二种石。炼饵服之。轻身。神仙。生益州山谷。 $q{《名医别录》}：【朴消】味辛。大寒。无毒。主治胃中食饮热结。破留血闭绝。停痰痞满。推陈致新。炼之白如银。能寒能热能滑能涩。能辛能苦能咸能酸。入地千岁不变。色青白者佳。黄者伤人。赤者杀人。一名消石朴。生益州有咸水之阳。采无时。（畏麦句姜。） $q{《神农本草经》}：【消石】味苦寒。主治五藏积热。胃胀闭。涤去蓄结饮食。推陈致新。除邪气。炼之如膏。久服轻身。一名芒消。生益州山谷。 $q{《名医别录》}：【消石】味辛。大寒。无毒。主治五藏十二经脉中百二十疾。暴伤寒腹中大热。止烦满消渴。利小便及瘘蚀疮。天地至神之物。能化成十二种石。生益州。及武都陇西西羌。采无时。（萤火为之使。恶苦参苦菜。畏女菀。） $q{《名医别录》}：【芒消】味辛苦。大寒。主治五藏积聚。久热胃闭。除邪气。破留血腹中淡实结搏。通脉。利大小便及月水。破五淋。推陈致新。生于朴消。（石韦为之使。畏麦句姜。） $q{《药性论》}：【芒消】使。味咸，有小毒。能通女子月闭。癥瘕。下瘰疬，黄疸病。主堕胎。患漆疮。汁傅之。主时疾壅热。能散恶血。 $q{《药性论》}：【玄明粉】味辛甘。性冷。无毒。治心热烦躁。并五藏宿滞癥结。明目。退膈上虚热。消肿毒。此即朴消炼成者。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z5xEswEFq4S', 1, '{"title":"48、黄柏","description":"<p>48、$u{黄柏}：（黄蘗、蘗皮、黄柏）</p>\n<p>$q{《神农本草经》}：【黄蘗】味苦。寒。主治五藏肠胃中结气热。黄疸。肠痔。止泄痢。女子漏下赤白。阴阳蚀疮。一名檀桓。生汉中山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【蘗木】无毒。主治惊气在皮间。肌肤热赤起。目热赤痛。口疮。久服通神。【根】名檀桓。治心腹百病。安魂魄。不饥渴。久服轻身。延年通神。生汉中及永昌。（恶干漆。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":47,"yaoNames":"黄蘗,蘗皮,柏皮","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '48、$u{黄柏}：（黄蘗、蘗皮、黄柏） $q{《神农本草经》}：【黄蘗】味苦。寒。主治五藏肠胃中结气热。黄疸。肠痔。止泄痢。女子漏下赤白。阴阳蚀疮。一名檀桓。生汉中山谷。 $q{《名医别录》}：【蘗木】无毒。主治惊气在皮间。肌肤热赤起。目热赤痛。口疮。久服通神。【根】名檀桓。治心腹百病。安魂魄。不饥渴。久服轻身。延年通神。生汉中及永昌。（恶干漆。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7fWzC6yB6Yy', 1, '{"title":"49、栀子","description":"<p>49、$u{栀子}</p>\r\n<p>$q{《神农本草经》}：【栀子】味苦。寒。主治五内邪气。胃中热气。面赤酒疱鼻。白癞。赤癞。疮疡。一名木丹。生南阳川谷。</p>\r\n<p>$q{《名医别录》}：【栀子】大寒。无毒。主治目热赤痛。胸心大小肠大热。心中烦闷。胃中热气。一名越桃。生南阳。九月采实。暴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":48,"yaoNames":"木丹","aliases":[{"bieming":"肥栀子","name":"栀子"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '49、$u{栀子} $q{《神农本草经》}：【栀子】味苦。寒。主治五内邪气。胃中热气。面赤酒疱鼻。白癞。赤癞。疮疡。一名木丹。生南阳川谷。 $q{《名医别录》}：【栀子】大寒。无毒。主治目热赤痛。胸心大小肠大热。心中烦闷。胃中热气。一名越桃。生南阳。九月采实。暴干。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DDXydmiFQLK', 1, '{"title":"50、麦门冬","description":"<p>50、$u{麦门冬}</p>\r\n<p>$q{《神农本草经》}：【麦门冬】味甘。平。主治心腹结气。伤中。伤饱。胃络脉绝。羸瘦。短气。久服轻身。不老。不饥。生函谷川谷。</p>\r\n<p>$q{《名医别录》}：【麦门冬】微寒。无毒。主治身重目黄。心下支满。虚劳客热。口干燥渴。止呕吐。愈痿蹶。强阴。益精。消谷调中。保神。定肺气。安五藏。令人肥健。美颜色。有子。秦名羊韭。齐名爱韭。楚名乌韭。越名羊蓍。一名禹葭。一名禹余粮。叶如韭。冬夏长生。生函谷及堤坂肥土石间久废处。二月三月八月十月采。阴干。（地黄车前为之使。恶款冬苦瓠。畏苦参青蘘。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":49,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '50、$u{麦门冬} $q{《神农本草经》}：【麦门冬】味甘。平。主治心腹结气。伤中。伤饱。胃络脉绝。羸瘦。短气。久服轻身。不老。不饥。生函谷川谷。 $q{《名医别录》}：【麦门冬】微寒。无毒。主治身重目黄。心下支满。虚劳客热。口干燥渴。止呕吐。愈痿蹶。强阴。益精。消谷调中。保神。定肺气。安五藏。令人肥健。美颜色。有子。秦名羊韭。齐名爱韭。楚名乌韭。越名羊蓍。一名禹葭。一名禹余粮。叶如韭。冬夏长生。生函谷及堤坂肥土石间久废处。二月三月八月十月采。阴干。（地黄车前为之使。恶款冬苦瓠。畏苦参青蘘。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n7KV9vTrthx', 1, '{"title":"51、薯蓣","description":"<p>51、$u{薯蓣}</p>\r\n<p>$q{《神农本草经》}：【署预】味甘。温。主治伤中。补虚羸。除寒热邪气。补中。益气力。长肌肉。久服耳目聪明。轻身。不饥。延年。一名山芋。生嵩高山谷。</p>\r\n<p>$q{《名医别录》}：【署预】平。无毒。主治头面游风风头眼眩。下气。止腰痛。补虚劳羸瘦。充五藏。除烦热。强阴。秦楚名玉延。郑越名土藷。生嵩高。二月八月采根。暴干。（紫芝为之使。恶甘遂。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":50,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '51、$u{薯蓣} $q{《神农本草经》}：【署预】味甘。温。主治伤中。补虚羸。除寒热邪气。补中。益气力。长肌肉。久服耳目聪明。轻身。不饥。延年。一名山芋。生嵩高山谷。 $q{《名医别录》}：【署预】平。无毒。主治头面游风风头眼眩。下气。止腰痛。补虚劳羸瘦。充五藏。除烦热。强阴。秦楚名玉延。郑越名土藷。生嵩高。二月八月采根。暴干。（紫芝为之使。恶甘遂。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rOi0RaqbWeB', 1, '{"title":"52、薏苡仁","description":"<p>52、$u{薏苡仁}</p>\r\n<p>$q{《神农本草经》}：【薏苡人】味甘。微寒。主治筋急拘挛。不可屈伸。风湿痹。下气。久服轻身益气。其根下三虫。一名解蠡。生真定平泽。</p>\r\n<p>$q{《名医别录》}：【薏苡人】无毒。主除筋骨邪气不仁。利肠胃。消水肿。令人能食。一名屋菼。一名起实。一名赣。生真定。八月采实。采根无时。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":51,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '52、$u{薏苡仁} $q{《神农本草经》}：【薏苡人】味甘。微寒。主治筋急拘挛。不可屈伸。风湿痹。下气。久服轻身益气。其根下三虫。一名解蠡。生真定平泽。 $q{《名医别录》}：【薏苡人】无毒。主除筋骨邪气不仁。利肠胃。消水肿。令人能食。一名屋菼。一名起实。一名赣。生真定。八月采实。采根无时。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jD7lvOl6QAj', 1, '{"title":"53、葶苈子","description":"<p>53、$u{葶苈子}</p>\r\n<p>$q{《神农本草经》}：【葶苈】味辛苦。寒。治癥瘕积聚。结气。饮食寒热。破坚逐邪。通利水道。一名大室。一名大适。生藁城平泽。</p>\r\n<p>$q{《名医别录》}：【葶苈】大寒。无毒。下膀胱水。腹留热气。皮间邪水上出。面目肿。身暴中风热疿痒。利小腹。久服令人虚。一名丁历。一名蕇蒿。生藁城及田野。立夏后采实。阴干。（得酒良。榆皮为之使。恶僵蚕石龙芮。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":52,"yaoNames":"大室,大适","aliases":[{"bieming":"葶苈","name":"葶苈子"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '53、$u{葶苈子} $q{《神农本草经》}：【葶苈】味辛苦。寒。治癥瘕积聚。结气。饮食寒热。破坚逐邪。通利水道。一名大室。一名大适。生藁城平泽。 $q{《名医别录》}：【葶苈】大寒。无毒。下膀胱水。腹留热气。皮间邪水上出。面目肿。身暴中风热疿痒。利小腹。久服令人虚。一名丁历。一名蕇蒿。生藁城及田野。立夏后采实。阴干。（得酒良。榆皮为之使。恶僵蚕石龙芮。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IqTeSDitXRA', 1, '{"title":"54、通草","description":"<p>54、$u{通草}</p>\r\n<p>$q{《神农本草经》}：【通草】味辛。平。主去恶虫。除脾胃寒热。通利九窍。血脉。关节。令人不忘。一名附支。生石城山谷。</p>\r\n<p>$q{《名医别录》}：【通草】味甘。无毒。主治脾疸。常欲眠。心烦。哕出音声。治耳聋。散痈肿诸结不消。及金疮。恶疮。鼠瘘。踒折。齆鼻。息肉。堕胎。去三虫。一名丁翁。生石城及山阳。正月采枝。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":53,"yaoNames":"附支","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '54、$u{通草} $q{《神农本草经》}：【通草】味辛。平。主去恶虫。除脾胃寒热。通利九窍。血脉。关节。令人不忘。一名附支。生石城山谷。 $q{《名医别录》}：【通草】味甘。无毒。主治脾疸。常欲眠。心烦。哕出音声。治耳聋。散痈肿诸结不消。及金疮。恶疮。鼠瘘。踒折。齆鼻。息肉。堕胎。去三虫。一名丁翁。生石城及山阳。正月采枝。阴干。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nMnl8EhuWTn', 1, '{"title":"55、䗪虫","description":"<p>55、$u{䗪虫}</p>\r\n<p>$q{《神农本草经》}：【䗪虫】味咸。寒。主治心腹寒热洗洗。血积癥瘕。破坚。下血闭。生子大良。一名地鳖。生河东川泽。</p>\r\n<p>$q{《名医别录》}：【䗪虫】有毒。一名土鳖。生河东及沙中。人家墙壁下土中湿处。十月取暴干。（畏皂荚菖蒲。）</p>\r\n<p>$q{《药性论》}：【䗪虫】使。畏屋游。味苦咸。治月水不通。破恶血积聚。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":54,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '55、$u{䗪虫} $q{《神农本草经》}：【䗪虫】味咸。寒。主治心腹寒热洗洗。血积癥瘕。破坚。下血闭。生子大良。一名地鳖。生河东川泽。 $q{《名医别录》}：【䗪虫】有毒。一名土鳖。生河东及沙中。人家墙壁下土中湿处。十月取暴干。（畏皂荚菖蒲。） $q{《药性论》}：【䗪虫】使。畏屋游。味苦咸。治月水不通。破恶血积聚。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ozDrmO1Ighz', 1, '{"title":"56、矾石","description":"<p>56、$u{矾石}</p>\r\n<p>$q{《神农本草经》}：【矾石】味酸。寒。主治寒热。泄利。白沃。阴蚀。恶疮。目痛。坚骨齿。炼饵服之。轻身。不老增年。一名羽涅。生河西山谷。</p>\r\n<p>$q{《名医别录》}：【矾石】无毒。除固热在骨髓。去鼻中息肉。岐伯云久服伤人骨。能使铁为铜。一名羽泽。生河西及陇西武都石门。采无时。（甘草为之使。恶牡蛎。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":55,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '56、$u{矾石} $q{《神农本草经》}：【矾石】味酸。寒。主治寒热。泄利。白沃。阴蚀。恶疮。目痛。坚骨齿。炼饵服之。轻身。不老增年。一名羽涅。生河西山谷。 $q{《名医别录》}：【矾石】无毒。除固热在骨髓。去鼻中息肉。岐伯云久服伤人骨。能使铁为铜。一名羽泽。生河西及陇西武都石门。采无时。（甘草为之使。恶牡蛎。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q7UHJJ3ORHQ', 1, '{"title":"57、胶饴","description":"<p>57、$u{胶饴}（饴）</p>\r\n<p>$q{《名医别录》}：【饴糖】味甘。微温。主补虚乏。止渴。去血。</p>\r\n<p>$q{《日华子本草》}：【饴糖】益气力。消痰止嗽。并润五藏。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":56,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '57、$u{胶饴}（饴） $q{《名医别录》}：【饴糖】味甘。微温。主补虚乏。止渴。去血。 $q{《日华子本草》}：【饴糖】益气力。消痰止嗽。并润五藏。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MzvPguhXJ5G', 1, '{"title":"58、葛根","description":"<p>58、$u{葛根}</p>\r\n<p>$q{《神农本草经》}：【葛根】味甘。平。主治消渴。身大热。呕吐。诸痹。起阴气。解诸毒。【葛谷】治下痢十岁已上。一名鸡齐根。生汶山川谷。</p>\r\n<p>$q{《名医别录》}：【葛根】无毒。主治伤寒中风头痛。解肌发表出汗。开腠理。疗金疮。止痛。胁风痛。【生根汁】大寒。治消渴。伤寒壮热。【白葛】烧以粉疮。止痛断血。【花】主消酒。一名鹿藿。一名黄斤。生汶山。五月采根。暴干。（杀野葛巴豆百药毒。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":57,"yaoNames":"鸡齐根","aliases":[{"bieming":"生葛","name":"葛根"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '58、$u{葛根} $q{《神农本草经》}：【葛根】味甘。平。主治消渴。身大热。呕吐。诸痹。起阴气。解诸毒。【葛谷】治下痢十岁已上。一名鸡齐根。生汶山川谷。 $q{《名医别录》}：【葛根】无毒。主治伤寒中风头痛。解肌发表出汗。开腠理。疗金疮。止痛。胁风痛。【生根汁】大寒。治消渴。伤寒壮热。【白葛】烧以粉疮。止痛断血。【花】主消酒。一名鹿藿。一名黄斤。生汶山。五月采根。暴干。（杀野葛巴豆百药毒。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sx4xviDfH00', 1, '{"title":"59、豉","description":"<p>59、$u{豉}（香豉、盐豉、豆豉）</p>\r\n<p>$q{《名医别录》}：【豉】味苦。寒。无毒。主治伤寒头痛寒热。瘴气恶毒。烦躁满闷。虚劳喘吸。两脚疼冷。又杀六畜胎子诸毒。</p>\r\n<p>$q{《药性论》}：【豆豉】得醯良。杀六畜毒。味苦甘。主下血痢如刺者。豉一升。水渍才令相淹。煎一两沸。绞取汁。顿服。不差。可再服。又伤寒暴痢腹痛者。豉一升。薤白一握。切。以水三升。先煮薤。内豉。更煮汤。色黑。去豉。分为二服。不差再服。熬末。能止汗。主除烦躁。治时疾热病。发汗。又治阴茎上疮痛烂。豉一分。蚯蚓湿泥二分。水研和。涂上。干易。禁热食酒菜蒜。又寒热风。胸中疮。生者可捣为丸服。良。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":58,"yaoNames":"香豉,盐豉,豆豉","aliases":[{"bieming":"香豉","name":"豉"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '59、$u{豉}（香豉、盐豉、豆豉） $q{《名医别录》}：【豉】味苦。寒。无毒。主治伤寒头痛寒热。瘴气恶毒。烦躁满闷。虚劳喘吸。两脚疼冷。又杀六畜胎子诸毒。 $q{《药性论》}：【豆豉】得醯良。杀六畜毒。味苦甘。主下血痢如刺者。豉一升。水渍才令相淹。煎一两沸。绞取汁。顿服。不差。可再服。又伤寒暴痢腹痛者。豉一升。薤白一握。切。以水三升。先煮薤。内豉。更煮汤。色黑。去豉。分为二服。不差再服。熬末。能止汗。主除烦躁。治时疾热病。发汗。又治阴茎上疮痛烂。豉一分。蚯蚓湿泥二分。水研和。涂上。干易。禁热食酒菜蒜。又寒热风。胸中疮。生者可捣为丸服。良。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('14GklrlZE7t', 1, '{"title":"60、鳖甲","description":"<p>60、$u{鳖甲}</p>\r\n<p>$q{《神农本草经》}：【鳖甲】味咸。平。主治心腹癥瘕。坚积。寒热。去痞息肉。阴蚀。痔。恶肉。生丹阳池泽。</p>\r\n<p>$q{《名医别录》}：【鳖甲】无毒。主治温疟。血瘕。腰痛。小儿胁下坚。【肉】味甘。治伤中。益气。补不足。生丹阳。取无时。（恶矾石。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":59,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '60、$u{鳖甲} $q{《神农本草经》}：【鳖甲】味咸。平。主治心腹癥瘕。坚积。寒热。去痞息肉。阴蚀。痔。恶肉。生丹阳池泽。 $q{《名医别录》}：【鳖甲】无毒。主治温疟。血瘕。腰痛。小儿胁下坚。【肉】味甘。治伤中。益气。补不足。生丹阳。取无时。（恶矾石。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9BxIgk2gITY', 1, '{"title":"61、栝蒌","description":"<p>61、$u{栝楼实}</p>\r\n<p>$q{《神农本草经》}：【栝楼】味苦。寒。主治消渴。身热烦满。大热。补虚。安中。续绝伤。一名地楼。生弘农川谷。</p>\r\n<p>$q{《名医别录》}：【栝楼实】名黄瓜。治胸痹。悦泽人面。（枸杞为之使。恶干姜。畏牛膝干漆。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":60,"yaoNames":"栝蒌实,栝楼实,地楼,天花粉,瓜蒌实,栝楼,栝蒌仁","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '61、$u{栝楼实} $q{《神农本草经》}：【栝楼】味苦。寒。主治消渴。身热烦满。大热。补虚。安中。续绝伤。一名地楼。生弘农川谷。 $q{《名医别录》}：【栝楼实】名黄瓜。治胸痹。悦泽人面。（枸杞为之使。恶干姜。畏牛膝干漆。反乌头。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PLFElISYWYO', 1, '{"title":"62、薤白","description":"<p>62、$u{薤白}</p>\r\n<p>$q{《神农本草经》}：【薤】味辛。温。主治金创。创败。轻身。不饥。耐老。生鲁山平泽。</p>\r\n<p>$q{《名医别录》}：【薤】味苦。无毒。归骨。菜芝也。除寒热。去水气。温中。散结。利病人。诸疮中风寒水肿以涂之。生鲁山。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":61,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '62、$u{薤白} $q{《神农本草经》}：【薤】味辛。温。主治金创。创败。轻身。不饥。耐老。生鲁山平泽。 $q{《名医别录》}：【薤】味苦。无毒。归骨。菜芝也。除寒热。去水气。温中。散结。利病人。诸疮中风寒水肿以涂之。生鲁山。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZJN7O318dPD', 1, '{"title":"63、吴茱萸","description":"<p>63、$u{吴茱萸}</p>\r\n<p>$q{《神农本草经》}：【吴茱萸】味辛。温。主温中下气。止痛。咳逆。寒热。除湿血痹。逐风邪。开腠理。【根】杀三虫。一名藙。生上谷川谷。</p>\r\n<p>$q{《名医别录》}：【吴茱萸】大热。有小毒。主去痰冷。腹内绞痛。诸冷实不消。中恶。心腹痛。逆气。利五藏。【根白皮】杀蛲虫。治喉痹咳逆。止泄注。食不消。女子经产余血。疗白癣。生上谷及宛朐。九月九日采。阴干。（蓼实为之使。恶丹参消石白垩。畏紫石英。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":62,"yaoNames":"藙","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '63、$u{吴茱萸} $q{《神农本草经》}：【吴茱萸】味辛。温。主温中下气。止痛。咳逆。寒热。除湿血痹。逐风邪。开腠理。【根】杀三虫。一名藙。生上谷川谷。 $q{《名医别录》}：【吴茱萸】大热。有小毒。主去痰冷。腹内绞痛。诸冷实不消。中恶。心腹痛。逆气。利五藏。【根白皮】杀蛲虫。治喉痹咳逆。止泄注。食不消。女子经产余血。疗白癣。生上谷及宛朐。九月九日采。阴干。（蓼实为之使。恶丹参消石白垩。畏紫石英。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VBp4qtisnQR', 1, '{"title":"64、猪苓","description":"<p>64、$u{猪苓}</p>\r\n<p>$q{《神农本草经》}：【猪苓】味甘。平。主治痎疟。解毒。辟蛊疰不祥。利水道。久服轻身。耐老。一名猳猪矢。生衡山川谷。</p>\r\n<p>$q{《名医别录》}：【猪苓】味苦。无毒。生衡山及济阴宛朐。二月八月采。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":63,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '64、$u{猪苓} $q{《神农本草经》}：【猪苓】味甘。平。主治痎疟。解毒。辟蛊疰不祥。利水道。久服轻身。耐老。一名猳猪矢。生衡山川谷。 $q{《名医别录》}：【猪苓】味苦。无毒。生衡山及济阴宛朐。二月八月采。阴干。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1rOkrjGOCab', 1, '{"title":"65、赤石脂","description":"<p>65、$u{赤石脂}</p>\r\n<p>$q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。</p>\r\n<p>$q{《名医别录》}：【赤石脂】味甘酸辛。大温。无毒。主养心气。明目。益精。治腹痛。泄澼。下痢赤白。小便利。及痈疽疮痔。女子崩中漏下。产难。胞衣不出。久服补髓。好颜色。益智。不饥。轻身。延年。生济南射阳。及太山之阴。采无时。（恶大黄。畏芫花。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":64,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '65、$u{赤石脂} $q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。 $q{《名医别录》}：【赤石脂】味甘酸辛。大温。无毒。主养心气。明目。益精。治腹痛。泄澼。下痢赤白。小便利。及痈疽疮痔。女子崩中漏下。产难。胞衣不出。久服补髓。好颜色。益智。不饥。轻身。延年。生济南射阳。及太山之阴。采无时。（恶大黄。畏芫花。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7nTRDUdzsoW', 1, '{"title":"66、甘遂","description":"<p>66、$u{甘遂}</p>\r\n<p>$q{《神农本草经》}：【甘遂】味苦。寒。主治大腹疝瘕。腹满。面目浮肿。留饮宿食。破癥坚积聚。利水谷道。一名主田。生中山川谷。</p>\r\n<p>$q{《名医别录》}：【甘遂】味甘。大寒。有毒。主下五水。散膀胱留热。皮中痞。热气肿满。一名甘藁。一名陵藁。一名陵泽。一名重泽。生中山。二月采根。阴干。（瓜蒂为之使。恶远志。反甘草。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":65,"yaoNames":"主田","aliases":[{"bieming":"甘遂末","name":"甘遂"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '66、$u{甘遂} $q{《神农本草经》}：【甘遂】味苦。寒。主治大腹疝瘕。腹满。面目浮肿。留饮宿食。破癥坚积聚。利水谷道。一名主田。生中山川谷。 $q{《名医别录》}：【甘遂】味甘。大寒。有毒。主下五水。散膀胱留热。皮中痞。热气肿满。一名甘藁。一名陵藁。一名陵泽。一名重泽。生中山。二月采根。阴干。（瓜蒂为之使。恶远志。反甘草。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1n7R7kiLFv1', 1, '{"title":"67、巴豆","description":"<p>67、$u{巴豆}</p>\r\n<p>$q{《神农本草经》}：【巴豆】味辛。温。主治伤寒。温疟。寒热。破癥瘕。结坚积聚。留饮。淡澼。大腹水胀。荡练五藏六府。开通闭寒。利水谷道。去恶肉。除鬼蛊毒注邪物。杀虫鱼。一名巴椒。生巴郡川谷。</p>\r\n<p>$q{《名医别录》}：【巴豆】生温熟寒。有大毒。主治女子月闭。烂胎。金创脓血。不利丈夫阴。杀斑猫毒。可练饵之。益血脉。令人色好。变化与鬼神通。生巴郡。八月采实。阴干。用之去心皮。（芫花之使。恶蘘草。畏大黄黄连藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":66,"yaoNames":"巴椒","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '67、$u{巴豆} $q{《神农本草经》}：【巴豆】味辛。温。主治伤寒。温疟。寒热。破癥瘕。结坚积聚。留饮。淡澼。大腹水胀。荡练五藏六府。开通闭寒。利水谷道。去恶肉。除鬼蛊毒注邪物。杀虫鱼。一名巴椒。生巴郡川谷。 $q{《名医别录》}：【巴豆】生温熟寒。有大毒。主治女子月闭。烂胎。金创脓血。不利丈夫阴。杀斑猫毒。可练饵之。益血脉。令人色好。变化与鬼神通。生巴郡。八月采实。阴干。用之去心皮。（芫花之使。恶蘘草。畏大黄黄连藜芦。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ul8euTuPbq0', 1, '{"title":"68、雄黄","description":"<p>68、$u{雄黄}</p>\r\n<p>$q{《神农本草经》}：【雄黄】味苦。平。寒。主治寒热。鼠瘘。恶疮。疽痔。死肌。杀精物。恶鬼。邪气。百虫。毒肿。胜五兵。炼食之。轻身。神仙。一名黄食石。生武都山谷。</p>\r\n<p>$q{《名医别录》}：【雄黄】味甘。大温。有毒。主治疥虫。𧏾疮。目痛。鼻中息肉。及绝筋。破骨。百节中大积聚。癖气。中恶。腹痛。鬼疰。杀诸蛇虺毒。解藜芦毒。悦泽人面。饵服之。皆飞入人脑中。胜鬼神。延年益寿。保中不饥。得铜可作金。生武都敦煌山之阳。采无时。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":67,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '68、$u{雄黄} $q{《神农本草经》}：【雄黄】味苦。平。寒。主治寒热。鼠瘘。恶疮。疽痔。死肌。杀精物。恶鬼。邪气。百虫。毒肿。胜五兵。炼食之。轻身。神仙。一名黄食石。生武都山谷。 $q{《名医别录》}：【雄黄】味甘。大温。有毒。主治疥虫。𧏾疮。目痛。鼻中息肉。及绝筋。破骨。百节中大积聚。癖气。中恶。腹痛。鬼疰。杀诸蛇虺毒。解藜芦毒。悦泽人面。饵服之。皆飞入人脑中。胜鬼神。延年益寿。保中不饥。得铜可作金。生武都敦煌山之阳。采无时。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gFgG38KNuFm', 1, '{"title":"69、蜀漆","description":"<p>69、$u{蜀漆}</p>\r\n<p>$q{《神农本草经》}：【蜀漆】味辛。平。主治疟。及咳逆寒热。腹中癥坚。痞结。积聚。邪气。蛊毒。鬼疰。生江林山川谷。</p>\r\n<p>$q{《名医别录》}：【蜀漆】微温。有毒。主治胸中邪结气。吐出之。生江林山及蜀汉中。恒山苗也。五月采叶。阴干。（栝楼为之使。恶贯众。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":68,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '69、$u{蜀漆} $q{《神农本草经》}：【蜀漆】味辛。平。主治疟。及咳逆寒热。腹中癥坚。痞结。积聚。邪气。蛊毒。鬼疰。生江林山川谷。 $q{《名医别录》}：【蜀漆】微温。有毒。主治胸中邪结气。吐出之。生江林山及蜀汉中。恒山苗也。五月采叶。阴干。（栝楼为之使。恶贯众。）', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CdBvjhzVtG6', 1, '{"title":"70、小麦","description":"<p>70、$u{小麦}</p>\r\n<p>$q{《名医别录》}：【小麦】味甘。微寒。无毒。主除热。止燥渴咽干。利小便。养肝气。止漏血唾血。以作【曲】。温。消谷。止痢。以作【面】。温。不能消热。止烦。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":69,"yaoNames":"","aliases":[{"bieming":"小麦汁","name":"小麦"},{"bieming":"小麦粥","name":"小麦"},{"bieming":"麦粥","name":"小麦"}],"volume":"中药"}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '70、$u{小麦} $q{《名医别录》}：【小麦】味甘。微寒。无毒。主除热。止燥渴咽干。利小便。养肝气。止漏血唾血。以作【曲】。温。消谷。止痢。以作【面】。温。不能消热。止烦。', '2024-09-14T16:56:58.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DouuvvsGgSZ', 1, '{"title":"71、大麦","description":"<p>71、$u{大麦}</p>\r\n<p>$q{《名医别录》}：【大麦】味咸。温微寒。无毒。主治消渴。除热。益气。调中。又云令人多热。为五谷长。（食蜜为之使。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":70,"yaoNames":"","aliases":[{"bieming":"大麦粥","name":"大麦"},{"bieming":"大麦粥汁","name":"大麦"}],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '71、$u{大麦} $q{《名医别录》}：【大麦】味咸。温微寒。无毒。主治消渴。除热。益气。调中。又云令人多热。为五谷长。（食蜜为之使。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('udN4qy4NAcw', 1, '{"title":"72、苦参","description":"<p>72、$u{苦参}</p>\r\n<p>$q{《神农本草经》}：【苦参】味苦。寒。主治心腹结气。癥瘕。积聚。黄疸。溺有余沥。逐水。除痈肿。补中。明目。止泪。一名水槐。一名苦。生汝南山谷。</p>\r\n<p>$q{《名医别录》}：【苦参】无毒。养肝胆气。安五藏。定志。益精。利九窍。除伏热。肠澼。止渴。醒酒。小便黄赤。治恶疮。下部慝。平胃气。令人嗜食。轻身。一名地槐。一名菟槐。一名骄槐。一名白茎。一名虎麻。一名岑茎。一名禄白。一名陵郎。生汝南及田野。三月八月十月采根。暴干。（玄参为之使。恶贝母漏芦菟丝。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":71,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '72、$u{苦参} $q{《神农本草经》}：【苦参】味苦。寒。主治心腹结气。癥瘕。积聚。黄疸。溺有余沥。逐水。除痈肿。补中。明目。止泪。一名水槐。一名苦。生汝南山谷。 $q{《名医别录》}：【苦参】无毒。养肝胆气。安五藏。定志。益精。利九窍。除伏热。肠澼。止渴。醒酒。小便黄赤。治恶疮。下部慝。平胃气。令人嗜食。轻身。一名地槐。一名菟槐。一名骄槐。一名白茎。一名虎麻。一名岑茎。一名禄白。一名陵郎。生汝南及田野。三月八月十月采根。暴干。（玄参为之使。恶贝母漏芦菟丝。反藜芦。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VbIDIYURZdR', 1, '{"title":"73、赤消","description":"<p>73、$u{赤消}（消石）</p>\r\n<p>$q{《神农本草经》}：【朴消】味苦。寒。主治百病。除寒热邪气。逐六府积聚。结固留癖。能化七十二种石。炼饵服之。轻身。神仙。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【朴消】味辛。大寒。无毒。主治胃中食饮热结。破留血闭绝。停痰痞满。推陈致新。炼之白如银。能寒能热能滑能涩。能辛能苦能咸能酸。入地千岁不变。色青白者佳。黄者伤人。赤者杀人。一名消石朴。生益州有咸水之阳。采无时。（畏麦句姜。）</p>\r\n<p>$q{《神农本草经》}：【消石】味苦寒。主治五藏积热。胃胀闭。涤去蓄结饮食。推陈致新。除邪气。炼之如膏。久服轻身。一名芒消。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【消石】味辛。大寒。无毒。主治五藏十二经脉中百二十疾。暴伤寒腹中大热。止烦满消渴。利小便及瘘蚀疮。天地至神之物。能化成十二种石。生益州。及武都陇西西羌。采无时。（萤火为之使。恶苦参苦菜。畏女菀。）</p>\r\n<p>$q{《名医别录》}：【芒消】味辛苦。大寒。主治五藏积聚。久热胃闭。除邪气。破留血腹中淡实结搏。通脉。利大小便及月水。破五淋。推陈致新。生于朴消。（石韦为之使。畏麦句姜。）</p>\r\n<p>$q{《药性论》}：【芒消】使。味咸，有小毒。能通女子月闭。癥瘕。下瘰疬，黄疸病。主堕胎。患漆疮。汁傅之。主时疾壅热。能散恶血。</p>\r\n<p>$q{《药性论》}：【玄明粉】味辛甘。性冷。无毒。治心热烦躁。并五藏宿滞癥结。明目。退膈上虚热。消肿毒。此即朴消炼成者。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":72,"yaoNames":"硝石,消石,赤硝","aliases":[{"bieming":"硝石","name":"赤消"}],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '73、$u{赤消}（消石） $q{《神农本草经》}：【朴消】味苦。寒。主治百病。除寒热邪气。逐六府积聚。结固留癖。能化七十二种石。炼饵服之。轻身。神仙。生益州山谷。 $q{《名医别录》}：【朴消】味辛。大寒。无毒。主治胃中食饮热结。破留血闭绝。停痰痞满。推陈致新。炼之白如银。能寒能热能滑能涩。能辛能苦能咸能酸。入地千岁不变。色青白者佳。黄者伤人。赤者杀人。一名消石朴。生益州有咸水之阳。采无时。（畏麦句姜。） $q{《神农本草经》}：【消石】味苦寒。主治五藏积热。胃胀闭。涤去蓄结饮食。推陈致新。除邪气。炼之如膏。久服轻身。一名芒消。生益州山谷。 $q{《名医别录》}：【消石】味辛。大寒。无毒。主治五藏十二经脉中百二十疾。暴伤寒腹中大热。止烦满消渴。利小便及瘘蚀疮。天地至神之物。能化成十二种石。生益州。及武都陇西西羌。采无时。（萤火为之使。恶苦参苦菜。畏女菀。） $q{《名医别录》}：【芒消】味辛苦。大寒。主治五藏积聚。久热胃闭。除邪气。破留血腹中淡实结搏。通脉。利大小便及月水。破五淋。推陈致新。生于朴消。（石韦为之使。畏麦句姜。） $q{《药性论》}：【芒消】使。味咸，有小毒。能通女子月闭。癥瘕。下瘰疬，黄疸病。主堕胎。患漆疮。汁傅之。主时疾壅热。能散恶血。 $q{《药性论》}：【玄明粉】味辛甘。性冷。无毒。治心热烦躁。并五藏宿滞癥结。明目。退膈上虚热。消肿毒。此即朴消炼成者。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dgPXrO7Zcb7', 1, '{"title":"74、升麻","description":"<p>74、$u{升麻}</p>\r\n<p>$q{《神农本草经》}：【升麻】味甘。平。解百毒。杀百精老物殃鬼。辟温疫瘴气邪气蛊毒。久服不夭。一名周麻。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【升麻】味苦。微寒。无毒。主解毒入口皆吐出。中恶腹痛。时气毒疠。头痛寒热。风肿诸毒。喉痛口疮。久服轻身长年。生益州。二月八月采根。日干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":73,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '74、$u{升麻} $q{《神农本草经》}：【升麻】味甘。平。解百毒。杀百精老物殃鬼。辟温疫瘴气邪气蛊毒。久服不夭。一名周麻。生益州山谷。 $q{《名医别录》}：【升麻】味苦。微寒。无毒。主解毒入口皆吐出。中恶腹痛。时气毒疠。头痛寒热。风肿诸毒。喉痛口疮。久服轻身长年。生益州。二月八月采根。日干。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UCM21bJfrih', 1, '{"title":"75、茵陈蒿","description":"<p>75、$u{茵陈蒿}</p>\r\n<p>$q{《神农本草经》}：【茵陈蒿】味苦。平。主治风湿寒热邪气。热结黄疸。久服轻身。益气。耐老。生太山。</p>\r\n<p>$q{《名医别录》}：【茵陈蒿】微寒。无毒。主治通身发黄。小便不利。除头热。去伏瘕。久服面白悦。长年。白兔食之仙。生太山及丘陵坂岸上。五月及立秋采。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":74,"yaoNames":"","aliases":[{"bieming":"茵陈蒿末","name":"茵陈蒿"}],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '75、$u{茵陈蒿} $q{《神农本草经》}：【茵陈蒿】味苦。平。主治风湿寒热邪气。热结黄疸。久服轻身。益气。耐老。生太山。 $q{《名医别录》}：【茵陈蒿】微寒。无毒。主治通身发黄。小便不利。除头热。去伏瘕。久服面白悦。长年。白兔食之仙。生太山及丘陵坂岸上。五月及立秋采。阴干。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nosq7W5OJnv', 1, '{"title":"76、白头翁","description":"<p>76、$u{白头翁}</p>\r\n<p>$q{《神农本草经》}：【白头翁】味苦。温。主治温疟。狂易。寒热。癥瘕积聚。瘿气。逐血。止痛。治金创。一名野丈人。一名胡王使者。生嵩山山谷。</p>\r\n<p>$q{《名医别录》}：【白头翁】有毒。主治鼻衄。一名奈何草。生嵩山及田野。四月采。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":75,"yaoNames":"胡王使者,野丈人","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '76、$u{白头翁} $q{《神农本草经》}：【白头翁】味苦。温。主治温疟。狂易。寒热。癥瘕积聚。瘿气。逐血。止痛。治金创。一名野丈人。一名胡王使者。生嵩山山谷。 $q{《名医别录》}：【白头翁】有毒。主治鼻衄。一名奈何草。生嵩山及田野。四月采。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Iru92bFSKGK', 1, '{"title":"77、秦皮","description":"<p>77、$u{秦皮}</p>\r\n<p>$q{《神农本草经》}：【秦皮】味苦。微寒。主治风寒湿痹。洗洗寒气。除热。目中青翳。白膜。久服头不白。轻身。生庐江川谷。</p>\r\n<p>$q{《名医别录》}：【秦皮】大寒。无毒。主治男子少精。妇人带下。小儿痫。身热。可作洗目汤。久服皮肤光泽。肥大。有子。一名岑皮。一名石檀。生庐江及宛朐。二月八月采皮。阴干。（大戟为之使。恶吴茱萸。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":76,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '77、$u{秦皮} $q{《神农本草经》}：【秦皮】味苦。微寒。主治风寒湿痹。洗洗寒气。除热。目中青翳。白膜。久服头不白。轻身。生庐江川谷。 $q{《名医别录》}：【秦皮】大寒。无毒。主治男子少精。妇人带下。小儿痫。身热。可作洗目汤。久服皮肤光泽。肥大。有子。一名岑皮。一名石檀。生庐江及宛朐。二月八月采皮。阴干。（大戟为之使。恶吴茱萸。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aDnno23iRr4', 1, '{"title":"78、竹茹","description":"<p>78、$u{竹茹}</p>\r\n<p>$q{《名医别录》}：【淡竹-皮茹】微寒。主治呕啘。温气寒热。吐血。崩中。溢筋。</p>\r\n<p>$q{《药性论》}：【青竹茹】使。味甘。能止肺痿唾血。鼻衄。治五痔。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":77,"yaoNames":"生竹茹","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '78、$u{竹茹} $q{《名医别录》}：【淡竹-皮茹】微寒。主治呕啘。温气寒热。吐血。崩中。溢筋。 $q{《药性论》}：【青竹茹】使。味甘。能止肺痿唾血。鼻衄。治五痔。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lzOM54GtZJW', 1, '{"title":"79、贝母","description":"<p>79、$u{贝母}</p>\r\n<p>$q{《神农本草经》}：【贝母】味辛。平。主治伤寒。烦热。淋沥。邪气。疝瘕。喉痹。乳难。金疮。风痉。一名空草。生晋地。</p>\r\n<p>$q{《名医别录》}：【贝母】味苦。微寒。无毒。主治腹中结实。心下满。洗洗恶风寒。目眩项直。咳嗽上气。止烦热渴。出汗。安五藏。利骨髓。一名药实。一名苦华。一名苦菜。一名商草。一名勤母。生晋地。十月采根。暴干。（厚朴白薇为之使。恶桃花。畏秦椒礜石莽草。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":78,"yaoNames":"空草","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '79、$u{贝母} $q{《神农本草经》}：【贝母】味辛。平。主治伤寒。烦热。淋沥。邪气。疝瘕。喉痹。乳难。金疮。风痉。一名空草。生晋地。 $q{《名医别录》}：【贝母】味苦。微寒。无毒。主治腹中结实。心下满。洗洗恶风寒。目眩项直。咳嗽上气。止烦热渴。出汗。安五藏。利骨髓。一名药实。一名苦华。一名苦菜。一名商草。一名勤母。生晋地。十月采根。暴干。（厚朴白薇为之使。恶桃花。畏秦椒礜石莽草。反乌头。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A05Whol2xOv', 1, '{"title":"80、鸡子白","description":"<p>80、$u{鸡子白}</p>\r\n<p>$q{《神农本草经》}：【鸡子】主除热火疮。治痫痓。可作虎魄神物。生朝鲜平泽。</p>\r\n<p>$q{《名医别录》}：【鸡卵白】微寒。治目热赤痛。除心下伏热。止烦满。咳逆。小儿下泄。妇人产难。胞衣不出。醯渍之一宿。治黄疸。破大烦热。【鸡卵中白皮】主治久咳结气。得麻黄紫菀和服之立已。生朝鲜。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":79,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '80、$u{鸡子白} $q{《神农本草经》}：【鸡子】主除热火疮。治痫痓。可作虎魄神物。生朝鲜平泽。 $q{《名医别录》}：【鸡卵白】微寒。治目热赤痛。除心下伏热。止烦满。咳逆。小儿下泄。妇人产难。胞衣不出。醯渍之一宿。治黄疸。破大烦热。【鸡卵中白皮】主治久咳结气。得麻黄紫菀和服之立已。生朝鲜。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wDdw8s8LVWE', 1, '{"title":"81、鸡子黄","description":"<p>81、$u{鸡子黄}（鸡黄）</p>\r\n<p>$q{《神农本草经》}：【鸡子】主除热火疮。治痫痓。可作虎魄神物。生朝鲜平泽。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":80,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '81、$u{鸡子黄}（鸡黄） $q{《神农本草经》}：【鸡子】主除热火疮。治痫痓。可作虎魄神物。生朝鲜平泽。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RCX32XC61We', 1, '{"title":"82、连翘","description":"<p>82、$u{连轺}[$q{《伤寒论》}曰：连翘根是。]</p>\r\n<p>$q{《神农本草经》}：【连翘】味苦。平。主治寒热。鼠瘘。瘰疬。痈肿。恶疮。瘿瘤。结热。蛊毒。一名异翘。一名兰华。一名折根。一名轵。一名三廉。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【连翘】无毒。去白虫。生太山。八月采。阴干。</p>\r\n<p>$q{《神农本草经》}：【翘根】味甘。寒平。主下热气。益阴精。令人面悦好。明目。久服轻身。耐老。生嵩高平泽。</p>\r\n<p>$q{《名医别录》}：【翘根】有小毒。以作蒸饮酒病人。生蒿高。二月八月采。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":81,"yaoNames":"连轺","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '82、$u{连轺}[$q{《伤寒论》}曰：连翘根是。] $q{《神农本草经》}：【连翘】味苦。平。主治寒热。鼠瘘。瘰疬。痈肿。恶疮。瘿瘤。结热。蛊毒。一名异翘。一名兰华。一名折根。一名轵。一名三廉。生太山山谷。 $q{《名医别录》}：【连翘】无毒。去白虫。生太山。八月采。阴干。 $q{《神农本草经》}：【翘根】味甘。寒平。主下热气。益阴精。令人面悦好。明目。久服轻身。耐老。生嵩高平泽。 $q{《名医别录》}：【翘根】有小毒。以作蒸饮酒病人。生蒿高。二月八月采。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jm7ItShKvM9', 1, '{"title":"83、潦水","description":"<p>83、$u{潦水}</p>\r\n<p>阙。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":82,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '83、$u{潦水} 阙。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
