INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wXt3DYxgQyQ', 1, '{"title":"85、荛花","description":"<p>85、$u{荛花}</p>\r\n<p>$q{《神农本草经》}：【荛花】味苦。寒。主治伤寒。温疟。下十二水。破积聚。大坚。癥瘕。荡涤肠胃中留癖。饮食寒热邪气。利水道。生咸阳川谷。</p>\r\n<p>$q{《名医别录》}：【荛花】味辛。微寒。有毒。主治痰饮咳嗽。生咸阳及河南中牟。六月采花。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":84,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '85、$u{荛花} $q{《神农本草经》}：【荛花】味苦。寒。主治伤寒。温疟。下十二水。破积聚。大坚。癥瘕。荡涤肠胃中留癖。饮食寒热邪气。利水道。生咸阳川谷。 $q{《名医别录》}：【荛花】味辛。微寒。有毒。主治痰饮咳嗽。生咸阳及河南中牟。六月采花。阴干。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3mS1d7xGocT', 1, '{"title":"86、人尿","description":"<p>86、$u{人尿}</p>\r\n<p>$q{《名医别录》}：【人溺】治寒热。头疼。温气。童男者尤良。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":85,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '86、$u{人尿} $q{《名医别录》}：【人溺】治寒热。头疼。温气。童男者尤良。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4W7eVdfu25M', 1, '{"title":"87、商陆根","description":"<p>87、$u{商陆根}</p>\r\n<p>$q{《神农本草经》}：【商陆】味辛。平。主治水胀。疝瘕。痹。熨除痈肿。杀鬼精物。一名䓪根。一名夜呼。生咸阳川谷。</p>\r\n<p>$q{《名医别录》}：【商陆】味酸。有毒。主治胸中邪气。水肿。痿痹。腹满洪直。疏五藏。散水气。如人形者。有神。生咸阳。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":86,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '87、$u{商陆根} $q{《神农本草经》}：【商陆】味辛。平。主治水胀。疝瘕。痹。熨除痈肿。杀鬼精物。一名䓪根。一名夜呼。生咸阳川谷。 $q{《名医别录》}：【商陆】味酸。有毒。主治胸中邪气。水肿。痿痹。腹满洪直。疏五藏。散水气。如人形者。有神。生咸阳。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WADWMmU3DAz', 1, '{"title":"88、梓白皮","description":"<p>88、$u{生梓白皮}</p>\r\n<p>$q{《神农本草经》}：【梓白皮】味苦。寒。主治热。去三虫。治目中患。【华】【叶】捣敷猪疮。饲猪肥大易养三倍。生河内山谷。</p>\r\n<p>$q{《名医别录》}：【梓白皮】无毒。主治目中患。生河内。又。【皮】主吐逆胃反。去三虫。小儿热疮。身头热烦。蚀疮。汤浴之。并封薄散傅。【嫩叶】主烂疮也。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":87,"yaoNames":"生梓白皮","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '88、$u{生梓白皮} $q{《神农本草经》}：【梓白皮】味苦。寒。主治热。去三虫。治目中患。【华】【叶】捣敷猪疮。饲猪肥大易养三倍。生河内山谷。 $q{《名医别录》}：【梓白皮】无毒。主治目中患。生河内。又。【皮】主吐逆胃反。去三虫。小儿热疮。身头热烦。蚀疮。汤浴之。并封薄散傅。【嫩叶】主烂疮也。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ovIpIDoCZlr', 1, '{"title":"89、天门冬","description":"<p>89、$u{天门冬}</p>\r\n<p>$q{《神农本草经》}：【天门冬】味苦。平。主治诸暴风湿偏痹。强骨髓。杀三虫。去伏尸。久服轻身。益气延年。一名颠勒。生奉高山谷。</p>\r\n<p>$q{《名医别录》}：【天门冬】味甘。大寒。无毒。保定肺气。去寒热。养肌肤。益气力。利小便。冷而能补。久服不饥。二月三月七月八月采根。暴干。[垣衣地黄为之使。畏曾青。]</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":88,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '89、$u{天门冬} $q{《神农本草经》}：【天门冬】味苦。平。主治诸暴风湿偏痹。强骨髓。杀三虫。去伏尸。久服轻身。益气延年。一名颠勒。生奉高山谷。 $q{《名医别录》}：【天门冬】味甘。大寒。无毒。保定肺气。去寒热。养肌肤。益气力。利小便。冷而能补。久服不饥。二月三月七月八月采根。暴干。[垣衣地黄为之使。畏曾青。]', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eblADTgt2Vi', 1, '{"title":"90、葳蕤","description":"<p>90、$u{葳蕤}</p>\r\n<p>$q{《名医别录》}：【萎蕤】无毒。主治心腹结气。虚热。湿毒。腰痛。茎中寒。及目痛眦烂泪出。一名荧。一名地节。一名玉竹。一名马熏。生太山及丘陵。立春后采。阴干。[畏卤咸。]</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":89,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '90、$u{葳蕤} $q{《名医别录》}：【萎蕤】无毒。主治心腹结气。虚热。湿毒。腰痛。茎中寒。及目痛眦烂泪出。一名荧。一名地节。一名玉竹。一名马熏。生太山及丘陵。立春后采。阴干。[畏卤咸。]', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o993hnzlGnH', 1, '{"title":"91、禹余粮","description":"<p>91、$u{禹余粮}（太一禹余粮）</p>\n<p>$q{《神农本草经》}：【太一禹余粮】味甘。平。主治咳逆上气。癥瘕。血闭。漏下。除邪气。久服耐寒暑。不饥。轻身。飞行千里。神仙。一名石脑。生太山山谷。</p>\n<p>$q{《名医别录》}：【太一禹余粮】无毒。主治肢节不利。大饱绝力身重。生太山。九月采。[杜仲为之使。畏贝母菖蒲铁落。]</p>\n<p>$q{《神农本草经》}：【禹余粮】味甘。寒。主治咳逆。寒热烦满。下利赤白血闭。癥瘕。大热。炼饵服之。不饥轻身。延年。生东海池泽。</p>\n<p>$q{《名医别录》}：【禹余粮】平。无毒。主治小腹痛结烦疼。一名白余粮。生东海及山岛中。或池泽中。</p>\n<p>$q{《药性论》}：【禹余粮】君。味咸。主治崩中。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":90,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '91、$u{禹余粮}（太一禹余粮） $q{《神农本草经》}：【太一禹余粮】味甘。平。主治咳逆上气。癥瘕。血闭。漏下。除邪气。久服耐寒暑。不饥。轻身。飞行千里。神仙。一名石脑。生太山山谷。 $q{《名医别录》}：【太一禹余粮】无毒。主治肢节不利。大饱绝力身重。生太山。九月采。[杜仲为之使。畏贝母菖蒲铁落。] $q{《神农本草经》}：【禹余粮】味甘。寒。主治咳逆。寒热烦满。下利赤白血闭。癥瘕。大热。炼饵服之。不饥轻身。延年。生东海池泽。 $q{《名医别录》}：【禹余粮】平。无毒。主治小腹痛结烦疼。一名白余粮。生东海及山岛中。或池泽中。 $q{《药性论》}：【禹余粮】君。味咸。主治崩中。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vTWUfkC7bQJ', 1, '{"title":"92、中裈灰","description":"<p>92、$u{中裈灰}</p>\r\n<p>阙。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":91,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '92、$u{中裈灰} 阙。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0uQxJy23uFD', 1, '{"title":"93、猪肤","description":"<p>93、$u{猪肤}</p>\r\n<p>阙。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":92,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '93、$u{猪肤} 阙。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E3Mbs1VE7cx', 1, '{"title":"94、铅丹","description":"<p>94、$u{铅丹}</p>\r\n<p>$q{《神农本草经》}：【铅丹】味辛。微寒。主治咳逆。胃反。惊痫。癫疾。除热。下气。炼化还成九光。久服通神明。生蜀郡平泽。</p>\r\n<p>$q{《名医别录》}：【铅丹】止小便利。除毒热脐挛。金疮溢血。生蜀郡。一名铅华。生于铅。</p>\r\n<p>$q{《药性论》}：【铅丹】君。主治惊悸。狂走。呕逆。消渴。煎膏用。止痛生肌。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":93,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '94、$u{铅丹} $q{《神农本草经》}：【铅丹】味辛。微寒。主治咳逆。胃反。惊痫。癫疾。除热。下气。炼化还成九光。久服通神明。生蜀郡平泽。 $q{《名医别录》}：【铅丹】止小便利。除毒热脐挛。金疮溢血。生蜀郡。一名铅华。生于铅。 $q{《药性论》}：【铅丹】君。主治惊悸。狂走。呕逆。消渴。煎膏用。止痛生肌。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H0hYG4VYtXF', 1, '{"title":"95、麻子仁","description":"<p>95、$u{麻子仁}（麻仁）</p>\r\n<p>$q{《神农本草经》}：【麻子】味甘。平。主补中益气。久服肥健不老。生太山川谷。</p>\r\n<p>$q{《名医别录》}：【麻子】无毒。主治中风汗出。逐水。利小便。破积血。复血脉。乳妇产后余疾。长发。可为沐药。久服神仙。九月采。入土中者贼人。生太山。（畏牡蛎白薇。恶茯苓。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":94,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '95、$u{麻子仁}（麻仁） $q{《神农本草经》}：【麻子】味甘。平。主补中益气。久服肥健不老。生太山川谷。 $q{《名医别录》}：【麻子】无毒。主治中风汗出。逐水。利小便。破积血。复血脉。乳妇产后余疾。长发。可为沐药。久服神仙。九月采。入土中者贼人。生太山。（畏牡蛎白薇。恶茯苓。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ASxxg5RfLMb', 1, '{"title":"96、山茱萸","description":"<p>96、$u{山茱萸}</p>\r\n<p>$q{《神农本草经》}：【山茱萸】味酸。平。主治心下邪气。寒热。温中。逐寒湿痹。去三虫。久服轻身。一名蜀枣。生汉中山谷。</p>\r\n<p>$q{《名医别录》}：【山茱萸】微温。无毒。主治肠胃风邪。寒热。疝瘕。头脑风。风气去来。鼻塞。目黄。耳聋。面疱。温中。下气。出汗。强阴。益精。安五藏。通九窍。止小便利。久服明目。强力。长年。一名鸡足。一名思益。一名寇实。生汉中及琅邪宛朐东海承县。九月十月采实。阴干。（蓼实为之使。恶桔梗防风防己。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":95,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '96、$u{山茱萸} $q{《神农本草经》}：【山茱萸】味酸。平。主治心下邪气。寒热。温中。逐寒湿痹。去三虫。久服轻身。一名蜀枣。生汉中山谷。 $q{《名医别录》}：【山茱萸】微温。无毒。主治肠胃风邪。寒热。疝瘕。头脑风。风气去来。鼻塞。目黄。耳聋。面疱。温中。下气。出汗。强阴。益精。安五藏。通九窍。止小便利。久服明目。强力。长年。一名鸡足。一名思益。一名寇实。生汉中及琅邪宛朐东海承县。九月十月采实。阴干。（蓼实为之使。恶桔梗防风防己。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ug7wsIcyGqw', 1, '{"title":"97、瞿麦","description":"<p>97、$u{瞿麦}</p>\r\n<p>$q{《神农本草经》}：【瞿麦】味苦。寒。主治关格诸癃结。小便不通。出刺。决痈肿。明目去翳。破胎堕子。下闭血。一名巨句麦。生太山川谷。</p>\r\n<p>$q{《名医别录》}：【瞿麦】味辛。无毒。主养肾气。逐膀胱邪逆。止霍乱。长毛发。一名大菊。一名大兰。生太山。立秋采实。阴干。（蘘草牡丹为之使。恶桑螵蛸。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":96,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '97、$u{瞿麦} $q{《神农本草经》}：【瞿麦】味苦。寒。主治关格诸癃结。小便不通。出刺。决痈肿。明目去翳。破胎堕子。下闭血。一名巨句麦。生太山川谷。 $q{《名医别录》}：【瞿麦】味辛。无毒。主养肾气。逐膀胱邪逆。止霍乱。长毛发。一名大菊。一名大兰。生太山。立秋采实。阴干。（蘘草牡丹为之使。恶桑螵蛸。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xoqRCmUZylQ', 1, '{"title":"98、赤小豆","description":"<p>98、$u{赤小豆}（赤豆）</p>\r\n<p>$q{《神农本草经》}：【赤小豆】主下水。排痈肿脓血。</p>\r\n<p>$q{《名医别录》}：【赤小豆】味甘酸。平温。无毒。主治寒热热中消渴。止泄。利小便。吐逆。卒澼。下胀满。又叶名【藿】。主治小便数。去烦热。</p>\r\n<p>$q{《药性论》}：【赤小豆】使。味甘。能消热毒痈肿。散恶血不尽。烦满。治水肿。皮肌胀满。擣薄涂痈肿上。主小儿急黄。烂疮。取汁令洗之。不过三度差。能令人美食。末与鸡子白调。涂热毒痈肿差。通气。健脾胃。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":97,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '98、$u{赤小豆}（赤豆） $q{《神农本草经》}：【赤小豆】主下水。排痈肿脓血。 $q{《名医别录》}：【赤小豆】味甘酸。平温。无毒。主治寒热热中消渴。止泄。利小便。吐逆。卒澼。下胀满。又叶名【藿】。主治小便数。去烦热。 $q{《药性论》}：【赤小豆】使。味甘。能消热毒痈肿。散恶血不尽。烦满。治水肿。皮肌胀满。擣薄涂痈肿上。主小儿急黄。烂疮。取汁令洗之。不过三度差。能令人美食。末与鸡子白调。涂热毒痈肿差。通气。健脾胃。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zdySy9e78kG', 1, '{"title":"99、瓜蒂","description":"<p>99、$u{瓜蒂}</p>\r\n<p>$q{《神农本草经》}：【瓜蒂】味苦。寒。有毒。主治大水。身面四肢浮肿。下水。杀蛊毒。咳逆上气。食诸果不消。病在胸腹中。皆吐下之。生嵩高平泽。</p>\r\n<p>$q{《名医别录》}：【瓜蒂】有毒。去鼻中息肉。治黄疸。其【花】主心痛咳逆。生嵩高。七月七日采。阴干。</p>\r\n<p>$q{《药性论》}：【瓜蒂】使。茎主鼻中息肉齆鼻。和小豆丁香吹鼻。治黄。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":98,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '99、$u{瓜蒂} $q{《神农本草经》}：【瓜蒂】味苦。寒。有毒。主治大水。身面四肢浮肿。下水。杀蛊毒。咳逆上气。食诸果不消。病在胸腹中。皆吐下之。生嵩高平泽。 $q{《名医别录》}：【瓜蒂】有毒。去鼻中息肉。治黄疸。其【花】主心痛咳逆。生嵩高。七月七日采。阴干。 $q{《药性论》}：【瓜蒂】使。茎主鼻中息肉齆鼻。和小豆丁香吹鼻。治黄。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nb7XmSpD8Iu', 1, '{"title":"100、海藻","description":"<p>100、$u{海藻}</p>\r\n<p>$q{《神农本草经》}：【海藻】味苦。寒。主治瘿瘤气。颈下核。破散结气。痈肿。癥瘕。坚气。腹中上下鸣。下十二水肿。一名落首。生东海。</p>\r\n<p>$q{《名医别录》}：【海藻】味咸。无毒。主治皮间积聚暴㿉。留气热结。利小便。一名藫。生东海。七月七日采。暴干。[反甘草。]</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":99,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '100、$u{海藻} $q{《神农本草经》}：【海藻】味苦。寒。主治瘿瘤气。颈下核。破散结气。痈肿。癥瘕。坚气。腹中上下鸣。下十二水肿。一名落首。生东海。 $q{《名医别录》}：【海藻】味咸。无毒。主治皮间积聚暴㿉。留气热结。利小便。一名藫。生东海。七月七日采。暴干。[反甘草。]', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hIgLFvn83se', 1, '{"title":"101、瓜瓣","description":"<p>101、$u{瓜瓣} 瓜子</p>\r\n<p>$q{《名医别录》}：【甘瓜子】主腹内结聚。破溃脓血。最为肠胃脾内壅要药。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":100,"yaoNames":"瓜子","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '101、$u{瓜瓣} 瓜子 $q{《名医别录》}：【甘瓜子】主腹内结聚。破溃脓血。最为肠胃脾内壅要药。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hmJnKWK15KJ', 1, '{"title":"102、皂荚","description":"<p>102、$u{皂荚}</p>\r\n<p>$q{《神农本草经》}：【皂荚】味辛咸。温。主治风痹。死肌。邪气。风头泪出。下水。利九窍。杀鬼精物。生雍州川谷。</p>\r\n<p>$q{《名医别录》}：【皂荚】有小毒。主治腹胀满。消谷。破咳嗽囊结。妇人胞下落。明目。益精。可为沐药。不入汤。生雍州及鲁邹县。如猪牙者良。九月十月采荚。阴干。（青葙子为之使。恶麦门冬。畏空青人参苦参。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":101,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '102、$u{皂荚} $q{《神农本草经》}：【皂荚】味辛咸。温。主治风痹。死肌。邪气。风头泪出。下水。利九窍。杀鬼精物。生雍州川谷。 $q{《名医别录》}：【皂荚】有小毒。主治腹胀满。消谷。破咳嗽囊结。妇人胞下落。明目。益精。可为沐药。不入汤。生雍州及鲁邹县。如猪牙者良。九月十月采荚。阴干。（青葙子为之使。恶麦门冬。畏空青人参苦参。）', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xfMKrX1fSwJ', 1, '{"title":"103、艾叶","description":"<p>103、$u{艾叶}</p>\r\n<p>$q{《名医别录》}：【艾叶】味苦。微温。无毒。主灸百病。可作煎。止下痢。吐血。下部𧏾疮。妇人漏血。利阴气。生肌肉。辟风寒。使人有子。一名冰台。一名医草。生田野。三月三日采。暴干。作煎。勿令见风。又【艾】生寒熟热。主下血。衄血。脓血痢。水煮及丸散任用。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":102,"yaoNames":"","aliases":[{"bieming":"艾叶","name":"艾"}],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '103、$u{艾叶} $q{《名医别录》}：【艾叶】味苦。微温。无毒。主灸百病。可作煎。止下痢。吐血。下部𧏾疮。妇人漏血。利阴气。生肌肉。辟风寒。使人有子。一名冰台。一名医草。生田野。三月三日采。暴干。作煎。勿令见风。又【艾】生寒熟热。主下血。衄血。脓血痢。水煮及丸散任用。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('biroLUs3POn', 1, '{"title":"104、水蛭","description":"<p>104、$u{水蛭}</p>\r\n<p>$q{《神农本草经》}：【水蛭】味咸。平。主逐恶血。瘀血。月闭。破血瘕。积聚。无子。利水道。生雷泽池泽。</p>\r\n<p>$q{《名医别录》}：【水蛭】味苦。微寒。有毒。主堕胎。一名蚑。一名至掌。生雷泽。五月六月采。暴干。</p>\r\n<p>$q{《药性论》}：【水蛭】使。主破女子月候不通。欲成血老癥块。能治血积聚。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":103,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '104、$u{水蛭} $q{《神农本草经》}：【水蛭】味咸。平。主逐恶血。瘀血。月闭。破血瘕。积聚。无子。利水道。生雷泽池泽。 $q{《名医别录》}：【水蛭】味苦。微寒。有毒。主堕胎。一名蚑。一名至掌。生雷泽。五月六月采。暴干。 $q{《药性论》}：【水蛭】使。主破女子月候不通。欲成血老癥块。能治血积聚。', '2024-09-14T16:56:59.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L1yNgzB2bxB', 1, '{"title":"105、虻虫","description":"<p>105、$u{虻虫}</p>\r\n<p>$q{《神农本草经》}：【木虻】味苦。平。主治目赤痛。眦伤泪出。瘀血。血闭。寒热酸𢠹。无子。一名魂常。生汉中川泽。</p>\r\n<p>$q{《名医别录》}：【木虻】有毒。生汉中。五月取。</p>\r\n<p>$q{《神农本草经》}：【蜚虻】味苦。微寒。主逐瘀血。破下血积。坚痞。癥瘕。寒热。通利血脉及九窍。生江夏川谷。</p>\r\n<p>$q{《名医别录》}：【蜚虻】有毒。主女子月水不通。积聚。除贼血在胸腹五藏者。及喉痹结塞。生江夏。五月取。腹有血者良。</p>\r\n<p>$q{《药性论》}：【虻虫】使。一名蜚虻。恶麻黄。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":104,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '105、$u{虻虫} $q{《神农本草经》}：【木虻】味苦。平。主治目赤痛。眦伤泪出。瘀血。血闭。寒热酸𢠹。无子。一名魂常。生汉中川泽。 $q{《名医别录》}：【木虻】有毒。生汉中。五月取。 $q{《神农本草经》}：【蜚虻】味苦。微寒。主逐瘀血。破下血积。坚痞。癥瘕。寒热。通利血脉及九窍。生江夏川谷。 $q{《名医别录》}：【蜚虻】有毒。主女子月水不通。积聚。除贼血在胸腹五藏者。及喉痹结塞。生江夏。五月取。腹有血者良。 $q{《药性论》}：【虻虫】使。一名蜚虻。恶麻黄。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fmrz9cHIBuv', 1, '{"title":"106、发髲","description":"<p>106、$u{乱发}</p>\r\n<p>$q{《名医别录》}：【乱发】微温。主治咳嗽。五淋。大小便不通。小儿惊痫。止血。鼻衄。烧之吹内立己。</p>\r\n<p>$q{《药性论》}：【乱发】使。味苦。能消瘀血。关格不通。利水道。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":105,"yaoNames":"乱发","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '106、$u{乱发} $q{《名医别录》}：【乱发】微温。主治咳嗽。五淋。大小便不通。小儿惊痫。止血。鼻衄。烧之吹内立己。 $q{《药性论》}：【乱发】使。味苦。能消瘀血。关格不通。利水道。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SsbIoYn21JT', 1, '{"title":"107、狼牙","description":"<p>107、$u{狼牙}</p>\r\n<p>$q{《神农本草经》}：【狼牙】味苦。寒。主治邪气。热气。疥瘙。恶疡疮。痔。去白虫。一名牙子。生淮南川谷。</p>\r\n<p>$q{《名医别录》}：【牙子】味酸。有毒。一名狼齿。一名狼子。一名犬牙。生淮南及宛朐。八月采根。暴干。中湿腐烂生衣者杀人。（芜荑为之使。恶地榆枣肌。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":106,"yaoNames":"","aliases":[{"bieming":"生狼牙","name":"狼牙"}],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '107、$u{狼牙} $q{《神农本草经》}：【狼牙】味苦。寒。主治邪气。热气。疥瘙。恶疡疮。痔。去白虫。一名牙子。生淮南川谷。 $q{《名医别录》}：【牙子】味酸。有毒。一名狼齿。一名狼子。一名犬牙。生淮南及宛朐。八月采根。暴干。中湿腐烂生衣者杀人。（芜荑为之使。恶地榆枣肌。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ErucDpix02e', 1, '{"title":"108、紫参","description":"<p>108、$u{紫参}</p>\r\n<p>$q{《神农本草经》}：【紫参】味苦辛。寒。主治心腹积聚。寒热邪气。通九窍。利大小便。一名牡蒙。生河西山谷。</p>\r\n<p>$q{《名医别录》}：【紫参】微寒。无毒。主治肠胃大热。唾血。衄血。肠中聚血。痈肿诸疮。止渴。益精。一名众戎。一名童肠。一名马行。生河西及宛朐。三月采根。火炙使紫色。（畏辛夷。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":107,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '108、$u{紫参} $q{《神农本草经》}：【紫参】味苦辛。寒。主治心腹积聚。寒热邪气。通九窍。利大小便。一名牡蒙。生河西山谷。 $q{《名医别录》}：【紫参】微寒。无毒。主治肠胃大热。唾血。衄血。肠中聚血。痈肿诸疮。止渴。益精。一名众戎。一名童肠。一名马行。生河西及宛朐。三月采根。火炙使紫色。（畏辛夷。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FCFRnbDhdjZ', 1, '{"title":"109、文蛤","description":"<p>109、$u{文蛤}</p>\r\n<p>$q{《神农本草经》}：【文蛤】治恶疮蚀五痔。生东海。</p>\r\n<p>$q{《名医别录》}：【文蛤】味咸。平。无毒。主治咳逆胸痹。腰痛胁急。鼠瘘。大孔出血。崩中漏下。生东海。表有文。取无时。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":108,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '109、$u{文蛤} $q{《神农本草经》}：【文蛤】治恶疮蚀五痔。生东海。 $q{《名医别录》}：【文蛤】味咸。平。无毒。主治咳逆胸痹。腰痛胁急。鼠瘘。大孔出血。崩中漏下。生东海。表有文。取无时。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PEcY2j6wjoH', 1, '{"title":"110、射干","description":"<p>110、$u{射干}（乌扇）</p>\r\n<p>$q{《神农本草经》}：【射干】味苦。平。主治咳逆上气。喉痹咽痛。不得消息。散结气。腹中邪逆。食饮大热。一名乌扇。一名乌蒲。生南阳川谷。</p>\r\n<p>$q{《名医别录》}：【射干】微温。有毒。主治老血在心肝脾间。咳唾。言语气臭。散胸中气。久服令人虚。一名乌翣。一名乌吹。一名草姜。生南阳田野。三月三日采根。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":109,"yaoNames":"","aliases":[{"bieming":"乌扇","name":"射干"}],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '110、$u{射干}（乌扇） $q{《神农本草经》}：【射干】味苦。平。主治咳逆上气。喉痹咽痛。不得消息。散结气。腹中邪逆。食饮大热。一名乌扇。一名乌蒲。生南阳川谷。 $q{《名医别录》}：【射干】微温。有毒。主治老血在心肝脾间。咳唾。言语气臭。散胸中气。久服令人虚。一名乌翣。一名乌吹。一名草姜。生南阳田野。三月三日采根。阴干。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uUYyOFNioq6', 1, '{"title":"111、苦酒","description":"<p>111、$u{苦酒}</p>\r\n<p>$q{《名医别录》}：【醋】味酸。温。无毒。主消痈肿。散水气。杀邪毒。</p>\r\n<p>$q{《本草经集注》}：【醋】以有苦味。俗呼为苦酒。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":110,"yaoNames":"","aliases":[{"bieming":"法醋","name":"苦酒"}],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '111、$u{苦酒} $q{《名医别录》}：【醋】味酸。温。无毒。主消痈肿。散水气。杀邪毒。 $q{《本草经集注》}：【醋】以有苦味。俗呼为苦酒。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('woIsPez0Ouc', 1, '{"title":"112、代赭石","description":"<p>112、$u{赭石}（代赭，代赭石）</p>\r\n<p>$q{《神农本草经》}：【代赭】味苦。寒。主治鬼疰。贼风。蛊毒。杀精物恶鬼。腹中毒邪气。女子赤沃漏下。一名须丸。生齐国山谷。</p>\r\n<p>$q{《名医别录》}：【代赭】味甘。无毒。主带下百病。产难。胞衣不出。堕胎。养血气。除五藏血脉中热。血痹血瘀。大人小儿惊气入腹。及阴痿不起。一名血师。生齐国。赤红青色。如鸡冠有泽。染爪甲不渝者良。采无时。（畏天雄。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":111,"yaoNames":"代赭,赭石","aliases":[{"bieming":"赭石","name":"代赭石"},{"bieming":"代赭","name":"代赭石"}],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '112、$u{赭石}（代赭，代赭石） $q{《神农本草经》}：【代赭】味苦。寒。主治鬼疰。贼风。蛊毒。杀精物恶鬼。腹中毒邪气。女子赤沃漏下。一名须丸。生齐国山谷。 $q{《名医别录》}：【代赭】味甘。无毒。主带下百病。产难。胞衣不出。堕胎。养血气。除五藏血脉中热。血痹血瘀。大人小儿惊气入腹。及阴痿不起。一名血师。生齐国。赤红青色。如鸡冠有泽。染爪甲不渝者良。采无时。（畏天雄。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eOGYO6mpDY8', 1, '{"title":"113、紫葳","description":"<p>113、$u{紫葳}</p>\r\n<p>$q{《神农本草经》}：【紫葳】味酸。微寒。主治妇人产乳余疾。崩中。癥瘕。血闭。寒热。羸瘦。养胎。生西海川谷。</p>\r\n<p>$q{《名医别录》}：【紫葳】无毒。【茎叶】味苦。无毒。治痿蹶。益气。一名陵苕。一名芺华。一名陵时。生西海及山阳。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":112,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '113、$u{紫葳} $q{《神农本草经》}：【紫葳】味酸。微寒。主治妇人产乳余疾。崩中。癥瘕。血闭。寒热。羸瘦。养胎。生西海川谷。 $q{《名医别录》}：【紫葳】无毒。【茎叶】味苦。无毒。治痿蹶。益气。一名陵苕。一名芺华。一名陵时。生西海及山阳。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('46OxMBGC5c7', 1, '{"title":"114、蜣螂","description":"<p>114、$u{蜣螂}</p>\r\n<p>$q{《神农本草经》}：【蜣螂】味咸。寒。主治小儿惊痫。瘛疭。腹胀。寒热。大人癫疾。狂易。一名蛣蜣。火熬之良。生长沙池泽。</p>\r\n<p>$q{《名医别录》}：【蜣螂】有毒。主治手足端寒。肢满贲豚。生长沙。五月五日取。蒸。藏之。临用当炙。勿置水中。令人吐。（畏羊肉石膏。）又。捣为丸。塞下部。引痔虫出尽。永瘥。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":113,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '114、$u{蜣螂} $q{《神农本草经》}：【蜣螂】味咸。寒。主治小儿惊痫。瘛疭。腹胀。寒热。大人癫疾。狂易。一名蛣蜣。火熬之良。生长沙池泽。 $q{《名医别录》}：【蜣螂】有毒。主治手足端寒。肢满贲豚。生长沙。五月五日取。蒸。藏之。临用当炙。勿置水中。令人吐。（畏羊肉石膏。）又。捣为丸。塞下部。引痔虫出尽。永瘥。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xg7IDhYbYBc', 1, '{"title":"115、鼠妇","description":"<p>115、$u{鼠妇}</p>\r\n<p>$q{《神农本草经》}：【鼠妇】味酸。温。主治气癃。不得小便。妇人月闭。血瘕。痫痓。寒热。利水道。一名负蟠。一名𧉅蝛。生魏郡平谷。</p>\r\n<p>$q{《名医别录》}：【鼠妇】微寒。无毒。一名蜲𧑓。生魏郡及人家地上。五月五日取。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":114,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '115、$u{鼠妇} $q{《神农本草经》}：【鼠妇】味酸。温。主治气癃。不得小便。妇人月闭。血瘕。痫痓。寒热。利水道。一名负蟠。一名𧉅蝛。生魏郡平谷。 $q{《名医别录》}：【鼠妇】微寒。无毒。一名蜲𧑓。生魏郡及人家地上。五月五日取。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GuKvN0MgqAD', 1, '{"title":"116、蜂窠","description":"<p>116、$u{蜂窠}</p>\r\n<p>$q{《神农本草经》}：【露蜂房】味苦。平。主治惊痫。瘛疭。寒热邪气。癫疾。鬼精蛊毒。肠痔。火熬之良。一名蜂场。生牂牁山谷。</p>\r\n<p>$q{《名医别录》}：【露蜂房】味咸。有毒。主治蜂毒。毒肿。一名百穿。一名蜂窠。生䍧牱。七月七日采。阴干。（恶干姜丹参黄芩芍药牡蛎。）又合乱发蛇皮三味合烧灰。酒服方寸匕。日二。治诸恶疽附骨痈。根在藏府。历节肿出。疖肿恶脉诸毒皆差。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":115,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '116、$u{蜂窠} $q{《神农本草经》}：【露蜂房】味苦。平。主治惊痫。瘛疭。寒热邪气。癫疾。鬼精蛊毒。肠痔。火熬之良。一名蜂场。生牂牁山谷。 $q{《名医别录》}：【露蜂房】味咸。有毒。主治蜂毒。毒肿。一名百穿。一名蜂窠。生䍧牱。七月七日采。阴干。（恶干姜丹参黄芩芍药牡蛎。）又合乱发蛇皮三味合烧灰。酒服方寸匕。日二。治诸恶疽附骨痈。根在藏府。历节肿出。疖肿恶脉诸毒皆差。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cbZNzdFF3uL', 1, '{"title":"117、煅灶下灰","description":"<p>117、$u{煅灶下灰}</p>\r\n<p>$q{《名医别录》}：【煅灶灰】主治癥瘕坚积。去邪恶气。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":116,"yaoNames":"","aliases":[{"bieming":"煅灶下灰","name":"煅灶灰"}],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '117、$u{煅灶下灰} $q{《名医别录》}：【煅灶灰】主治癥瘕坚积。去邪恶气。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BFmkWqxUMUs', 1, '{"title":"118、石韦","description":"<p>118、$u{石韦}</p>\r\n<p>$q{《神农本草经》}：【石韦】味苦。平。无毒。主治劳热。邪气。五癃闭不通。利小便水道。一名石䩾。生华阴山谷。</p>\r\n<p>$q{《名医别录》}：【石韦】味甘。无毒。主止烦。下气。通膀胱满。补五劳。安五藏。去恶风。益精气。一名石皮。用之去黄毛。毛射人肺。令人咳。不可治。生华阴。不闻水及人声者。良。二月采叶。阴干。（杏人为之使。得菖蒲良。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":117,"yaoNames":"石苇","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '118、$u{石韦} $q{《神农本草经》}：【石韦】味苦。平。无毒。主治劳热。邪气。五癃闭不通。利小便水道。一名石䩾。生华阴山谷。 $q{《名医别录》}：【石韦】味甘。无毒。主止烦。下气。通膀胱满。补五劳。安五藏。去恶风。益精气。一名石皮。用之去黄毛。毛射人肺。令人咳。不可治。生华阴。不闻水及人声者。良。二月采叶。阴干。（杏人为之使。得菖蒲良。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MN2tqTw73w6', 1, '{"title":"119、云母","description":"<p>119、$u{云母}</p>\r\n<p>$q{《神农本草经》}：【云母】味甘。平。主治身皮死肌。中风寒热。如在车船上。除邪气。安五藏。益子精。明目。久服轻身。延年。一名云珠。一名云华。一名云英。一名云液。一名云沙。一名磷石。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【云母】无毒。下气坚肌。续绝补中。治五劳七伤。虚损少气。止痢。久服悦泽不老。耐寒暑。志高神仙。一名云珠。色多赤。一名云华。五色具。一名云英。色多青。一名云液。色多白。一名云沙。色青黄。一名磷石。色正白。生太山齐庐山。及琅琊北定山石间。二月采。（泽泻为之使。畏鳝甲。反流水。恶徐长卿。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":118,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '119、$u{云母} $q{《神农本草经》}：【云母】味甘。平。主治身皮死肌。中风寒热。如在车船上。除邪气。安五藏。益子精。明目。久服轻身。延年。一名云珠。一名云华。一名云英。一名云液。一名云沙。一名磷石。生太山山谷。 $q{《名医别录》}：【云母】无毒。下气坚肌。续绝补中。治五劳七伤。虚损少气。止痢。久服悦泽不老。耐寒暑。志高神仙。一名云珠。色多赤。一名云华。五色具。一名云英。色多青。一名云液。色多白。一名云沙。色青黄。一名磷石。色正白。生太山齐庐山。及琅琊北定山石间。二月采。（泽泻为之使。畏鳝甲。反流水。恶徐长卿。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ZuiC9ADA2V', 1, '{"title":"120、菊花","description":"<p>120、$u{菊花}</p>\r\n<p>$q{《神农本草经》}：【菊花】味苦。平。主治风头眩肿痛。目欲脱。泪出。皮肤死肌。恶风湿痹。久服利血气。轻身。耐老延年。一名节华。生雍州川泽。</p>\r\n<p>$q{《名医别录》}：【菊花】味甘。无毒。主治腰痛去来陶陶。除胸中烦热。安肠胃。利五脉。调四肢。一名日精。一名女节。一名女华。一名女茎。一名更生。一名周盈。一名傅延年。一名阴成。生雍州及田野。正月采根。三月采叶。五月采茎。九月采花。十一月采实。皆阴干。（术枸杞根桑根白皮为之使。）</p>\r\n<p>$q{《药性论》}∶【甘菊花】使。能治热头风旋倒地。脑骨疼痛。身上诸风令消散。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":119,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '120、$u{菊花} $q{《神农本草经》}：【菊花】味苦。平。主治风头眩肿痛。目欲脱。泪出。皮肤死肌。恶风湿痹。久服利血气。轻身。耐老延年。一名节华。生雍州川泽。 $q{《名医别录》}：【菊花】味甘。无毒。主治腰痛去来陶陶。除胸中烦热。安肠胃。利五脉。调四肢。一名日精。一名女节。一名女华。一名女茎。一名更生。一名周盈。一名傅延年。一名阴成。生雍州及田野。正月采根。三月采叶。五月采茎。九月采花。十一月采实。皆阴干。（术枸杞根桑根白皮为之使。） $q{《药性论》}∶【甘菊花】使。能治热头风旋倒地。脑骨疼痛。身上诸风令消散。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i4fuYlgraQ2', 1, '{"title":"121、寒水石","description":"<p>121、$u{寒水石}</p>\r\n<p>$q{《神农本草经》}：【凝水石】味辛。寒。主治身热。腹中积聚邪气。皮中如火烧烂。烦满。水饮之。久服不饥。一名白水石。生常山山谷。</p>\r\n<p>$q{《名医别录》}：【凝水石】味甘。大寒。无毒。主除时气热盛。五藏伏热。胃中热。烦满。止渴。水肿。少腹痹。一名寒水石。一名凌水石。色如云母。可折者良。盐之精也。生常山山谷。又中水县及邯郸。（解巴豆毒。畏地榆。）</p>\r\n<p>$q{《药性论》}：【寒水石】能压丹石毒风。去心烦渴闷。解伤寒劳复。</p>\r\n<p>$q{《本草纲目》}：唐宋诸方寒水石是石膏。近方寒水石是长石方解石。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":120,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '121、$u{寒水石} $q{《神农本草经》}：【凝水石】味辛。寒。主治身热。腹中积聚邪气。皮中如火烧烂。烦满。水饮之。久服不饥。一名白水石。生常山山谷。 $q{《名医别录》}：【凝水石】味甘。大寒。无毒。主除时气热盛。五藏伏热。胃中热。烦满。止渴。水肿。少腹痹。一名寒水石。一名凌水石。色如云母。可折者良。盐之精也。生常山山谷。又中水县及邯郸。（解巴豆毒。畏地榆。） $q{《药性论》}：【寒水石】能压丹石毒风。去心烦渴闷。解伤寒劳复。 $q{《本草纲目》}：唐宋诸方寒水石是石膏。近方寒水石是长石方解石。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cSR0rsnZv7C', 1, '{"title":"122、白石脂","description":"<p>122、$u{白石脂}</p>\r\n<p>$q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。</p>\r\n<p>$q{《名医别录》}：【白石脂】味甘酸。平。无毒。主养肺气。厚肠。补骨髓。治五藏惊悸不足。心下烦。止腹痛。下水。小肠澼热溏。便脓血。女子崩中漏下。赤白沃。排痈疽疮痔。久服安心。不饥。轻身长年。生太山之阴。采无时。（得厚朴并米汁饮。止便脓。䴏屎为之使。恶松脂。畏黄芩。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":121,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '122、$u{白石脂} $q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。 $q{《名医别录》}：【白石脂】味甘酸。平。无毒。主养肺气。厚肠。补骨髓。治五藏惊悸不足。心下烦。止腹痛。下水。小肠澼热溏。便脓血。女子崩中漏下。赤白沃。排痈疽疮痔。久服安心。不饥。轻身长年。生太山之阴。采无时。（得厚朴并米汁饮。止便脓。䴏屎为之使。恶松脂。畏黄芩。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DThHnTLC5ju', 1, '{"title":"123、盐","description":"<p>123、$u{盐}</p>\r\n<p>$q{《名医别录》}：【卤咸】味咸。无毒。去五藏肠胃留热。结气。心下坚。食已呕逆。喘满。明目。目痛。生河盐池。</p>\r\n<p>$q{《名医别录》}：【戎盐】味咸。寒。无毒。主心腹痛。溺血。吐血。齿舌血出。一名胡盐。生胡盐山。及西羌北地。及酒泉福禄城东南角。北海青。南海赤。十月采。</p>\r\n<p>$q{《名医别录》}：【大盐】味甘咸。寒。无毒。主肠胃结热。喘逆。吐胸中病。生邯郸及河东。（漏芦为之使。）</p>\r\n<p>$q{《药性论》}：【盐】有小毒。能杀一切毒气。鬼疰气。主心痛中恶。或连腰脐者。盐如鸡子大。青布裹烧赤。内酒中。顿服。当吐恶物。主小儿卒不尿。安盐于脐中。灸之。面上五色疮。盐汤绵浸搨疮上。日五六度易。差。又和槐白皮切蒸。治脚气。又空心揩齿。少时吐水中洗眼。夜见小字。良。治妇人隐处疼痛者。盐青布裹熨之。主鬼疰尸疰。下部蚀疮。炒盐布裹坐熨之。兼主火灼疮。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":122,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '123、$u{盐} $q{《名医别录》}：【卤咸】味咸。无毒。去五藏肠胃留热。结气。心下坚。食已呕逆。喘满。明目。目痛。生河盐池。 $q{《名医别录》}：【戎盐】味咸。寒。无毒。主心腹痛。溺血。吐血。齿舌血出。一名胡盐。生胡盐山。及西羌北地。及酒泉福禄城东南角。北海青。南海赤。十月采。 $q{《名医别录》}：【大盐】味甘咸。寒。无毒。主肠胃结热。喘逆。吐胸中病。生邯郸及河东。（漏芦为之使。） $q{《药性论》}：【盐】有小毒。能杀一切毒气。鬼疰气。主心痛中恶。或连腰脐者。盐如鸡子大。青布裹烧赤。内酒中。顿服。当吐恶物。主小儿卒不尿。安盐于脐中。灸之。面上五色疮。盐汤绵浸搨疮上。日五六度易。差。又和槐白皮切蒸。治脚气。又空心揩齿。少时吐水中洗眼。夜见小字。良。治妇人隐处疼痛者。盐青布裹熨之。主鬼疰尸疰。下部蚀疮。炒盐布裹坐熨之。兼主火灼疮。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KeCSoielG2F', 1, '{"title":"124、紫石英","description":"<p>124、$u{紫石英}</p>\r\n<p>$q{《神农本草经》}：【紫石英】味甘。温。主治心腹咳逆邪气。补不足。女子风寒在子宫。绝孕十年无子。久服温中。轻身。延年。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【紫石英】味辛。无毒。主治上气心腹痛。寒热邪气结气。补心气不足。定惊悸。安魂魄。填下焦。止消渴。除胃中久寒。散痈肿。令人悦泽。生太山。采无时。（长石为之使。得茯苓人参芍药共治心中结气。得天雄菖蒲共治霍乱。畏扁青附子。不欲鳝甲黄连麦句姜。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":123,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '124、$u{紫石英} $q{《神农本草经》}：【紫石英】味甘。温。主治心腹咳逆邪气。补不足。女子风寒在子宫。绝孕十年无子。久服温中。轻身。延年。生太山山谷。 $q{《名医别录》}：【紫石英】味辛。无毒。主治上气心腹痛。寒热邪气结气。补心气不足。定惊悸。安魂魄。填下焦。止消渴。除胃中久寒。散痈肿。令人悦泽。生太山。采无时。（长石为之使。得茯苓人参芍药共治心中结气。得天雄菖蒲共治霍乱。畏扁青附子。不欲鳝甲黄连麦句姜。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SU1RKPtaRtw', 1, '{"title":"125、独活","description":"<p>125、$u{独活}</p>\r\n<p>$q{《神农本草经》}：【独活】味苦。平。主治风寒所击。金疮止痛。贲豚。痫痓。女子疝瘕。久服轻身。耐老。一名羌活。一名羌青。一名护羌使者。生雍州川谷。</p>\r\n<p>$q{《名医别录》}：【独活】味甘。微温。无毒。主治诸贼风。百节痛风无久新者。一名胡王使者。一名独摇草。此草得风不摇。无风自动。生雍州。或陇西南安。二月八月采根。暴干。（蠡实为之使。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":124,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '125、$u{独活} $q{《神农本草经》}：【独活】味苦。平。主治风寒所击。金疮止痛。贲豚。痫痓。女子疝瘕。久服轻身。耐老。一名羌活。一名羌青。一名护羌使者。生雍州川谷。 $q{《名医别录》}：【独活】味甘。微温。无毒。主治诸贼风。百节痛风无久新者。一名胡王使者。一名独摇草。此草得风不摇。无风自动。生雍州。或陇西南安。二月八月采根。暴干。（蠡实为之使。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E5qbjuyOeWF', 1, '{"title":"126、天雄","description":"<p>126、$u{天雄}</p>\r\n<p>$q{《神农本草经》}：【天雄】味辛。温。主治大风。寒湿痹。历节痛。拘挛缓急。破积聚。邪气。金创。强筋骨。轻身。健行。一名白幕。生少室山谷。</p>\r\n<p>$q{《名医别录》}：【天雄】味甘。大温。有大毒。主治头面风去来疼痛。心腹结积。关节重不能行步。除骨间痛。长阴气。强志。令人武勇。力作不倦。又堕胎。生少室。二月采根。阴干。（远志为之使。恶腐婢。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":125,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '126、$u{天雄} $q{《神农本草经》}：【天雄】味辛。温。主治大风。寒湿痹。历节痛。拘挛缓急。破积聚。邪气。金创。强筋骨。轻身。健行。一名白幕。生少室山谷。 $q{《名医别录》}：【天雄】味甘。大温。有大毒。主治头面风去来疼痛。心腹结积。关节重不能行步。除骨间痛。长阴气。强志。令人武勇。力作不倦。又堕胎。生少室。二月采根。阴干。（远志为之使。恶腐婢。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cc8oS8uz0SO', 1, '{"title":"127、白敛","description":"<p>127、$u{白敛}</p>\r\n<p>$q{《神农本草经》}：【白敛】味苦。平微寒。主治痈肿。疽疮。散结气。止痛。除热。目中赤。小儿惊痫。温疟。女子阴中肿痛。一名菟核。一名白草。生衡山山谷。</p>\r\n<p>$q{《名医别录》}：【白敛】味甘。无毒。主下赤白。杀火毒。一名白根。一名昆仑。生衡山。二月八月采根。暴干。（代赭为之使。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":126,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '127、$u{白敛} $q{《神农本草经》}：【白敛】味苦。平微寒。主治痈肿。疽疮。散结气。止痛。除热。目中赤。小儿惊痫。温疟。女子阴中肿痛。一名菟核。一名白草。生衡山山谷。 $q{《名医别录》}：【白敛】味甘。无毒。主下赤白。杀火毒。一名白根。一名昆仑。生衡山。二月八月采根。暴干。（代赭为之使。反乌头。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4u6mZMQmgVm', 1, '{"title":"128、豆黄卷","description":"<p>128、$u{豆黄卷}</p>\r\n<p>$q{《神农本草经》}：【大豆黄卷】味甘。平。主治湿痹。筋挛。膝痛。</p>\r\n<p>$q{《名医别录》}：【大豆黄卷】无毒。主治五藏胃气结积。益气。止毒。去黑皯。润泽皮毛。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":127,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '128、$u{豆黄卷} $q{《神农本草经》}：【大豆黄卷】味甘。平。主治湿痹。筋挛。膝痛。 $q{《名医别录》}：【大豆黄卷】无毒。主治五藏胃气结积。益气。止毒。去黑皯。润泽皮毛。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Z1Yvo95yHS', 1, '{"title":"129、曲","description":"<p>129、$u{曲}</p>\r\n<p>$q{《名医别录》}：【曲】温。消谷。止痢。</p>\r\n<p>$q{《嘉佑本草》}：【曲】味甘。大暖。疗藏府中风气。调中下气。开胃。消宿食。主霍乱。心膈气。痰逆。除烦。破癥结及补虚。去冷气。除肠胃塞。不下食。令人有颜色。六月作者良。陈久者入药。用之当炒令香。六畜食米胀欲死者。煮曲汁灌之。立消。落胎并下鬼胎。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":128,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '129、$u{曲} $q{《名医别录》}：【曲】温。消谷。止痢。 $q{《嘉佑本草》}：【曲】味甘。大暖。疗藏府中风气。调中下气。开胃。消宿食。主霍乱。心膈气。痰逆。除烦。破癥结及补虚。去冷气。除肠胃塞。不下食。令人有颜色。六月作者良。陈久者入药。用之当炒令香。六畜食米胀欲死者。煮曲汁灌之。立消。落胎并下鬼胎。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ODZGxGssDUt', 1, '{"title":"130、酸枣仁","description":"<p>130、$u{酸枣仁}</p>\r\n<p>$q{《神农本草经》}：【酸枣】味酸。平。主治心腹寒热。邪结气。四肢酸疼湿痹。久服安五藏。轻身。延年。生河东川泽。</p>\r\n<p>$q{《名医别录》}：【酸枣】无毒。主治烦心不得眠。脐上下痛。血转。久泄。虚汗。烦渴。补中。益肝气。坚筋骨。助阴气。令人肥健。生河东。八月采实。阴干。卅日成。（恶防己。）</p>\r\n<p>$q{《药性论》}：【酸枣人】主筋骨风。沙末作汤服之。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":129,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '130、$u{酸枣仁} $q{《神农本草经》}：【酸枣】味酸。平。主治心腹寒热。邪结气。四肢酸疼湿痹。久服安五藏。轻身。延年。生河东川泽。 $q{《名医别录》}：【酸枣】无毒。主治烦心不得眠。脐上下痛。血转。久泄。虚汗。烦渴。补中。益肝气。坚筋骨。助阴气。令人肥健。生河东。八月采实。阴干。卅日成。（恶防己。） $q{《药性论》}：【酸枣人】主筋骨风。沙末作汤服之。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('41gTtXf6W3Z', 1, '{"title":"131、干漆","description":"<p>131、$u{干漆}</p>\r\n<p>$q{《神农本草经》}：【干漆】味辛。温。无毒。主治绝伤。补中。续筋骨。填髓脑。安五藏。五缓六急。风寒湿痹。【生漆】去长虫。久服轻身。耐老。生汉中川谷。</p>\r\n<p>$q{《名医别录》}：【干漆】有毒。主治咳嗽。消瘀血。痞结。腰痛。女子疝瘕。利小肠。去蛔虫。生汉中。夏至后采。干之。（半夏为之使。畏鸡子。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":130,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '131、$u{干漆} $q{《神农本草经》}：【干漆】味辛。温。无毒。主治绝伤。补中。续筋骨。填髓脑。安五藏。五缓六急。风寒湿痹。【生漆】去长虫。久服轻身。耐老。生汉中川谷。 $q{《名医别录》}：【干漆】有毒。主治咳嗽。消瘀血。痞结。腰痛。女子疝瘕。利小肠。去蛔虫。生汉中。夏至后采。干之。（半夏为之使。畏鸡子。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('97tN0MlutoJ', 1, '{"title":"132、蛴螬","description":"<p>132、$u{蛴螬}</p>\r\n<p>$q{《神农本草经》}：【蛴螬】味咸。微温。主治恶血。血瘀痹气。破折血在胁下坚满痛。月闭。目中淫肤。青翳白膜。一名蟦蛴。生河内平泽。</p>\r\n<p>$q{《名医别录》}：【蛴螬】微寒。有毒。主治吐血在胸腹不去。及破骨踒折。血结。金疮内塞。产后中寒。下乳汁。一名蜰齐。一名㪍齐。生河内及人家积粪草中。取无时。反行者良。（蜚虻为之使。恶附子。）</p>\r\n<p>$q{《药性论》}：【蛴螬】臣。汁主滴目中去翳障。主血止痛。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":131,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '132、$u{蛴螬} $q{《神农本草经》}：【蛴螬】味咸。微温。主治恶血。血瘀痹气。破折血在胁下坚满痛。月闭。目中淫肤。青翳白膜。一名蟦蛴。生河内平泽。 $q{《名医别录》}：【蛴螬】微寒。有毒。主治吐血在胸腹不去。及破骨踒折。血结。金疮内塞。产后中寒。下乳汁。一名蜰齐。一名㪍齐。生河内及人家积粪草中。取无时。反行者良。（蜚虻为之使。恶附子。） $q{《药性论》}：【蛴螬】臣。汁主滴目中去翳障。主血止痛。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A2daxyQ36Xs', 1, '{"title":"133、獭肝","description":"<p>133、$u{獭肝}</p>\r\n<p>$q{《名医别录》}：【獭肝】味甘。有毒。主治鬼疰蛊毒。却鱼鲠。止久嗽。烧服之。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":132,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '133、$u{獭肝} $q{《名医别录》}：【獭肝】味甘。有毒。主治鬼疰蛊毒。却鱼鲠。止久嗽。烧服之。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CPNE5J4Tnwm', 1, '{"title":"134、款冬花","description":"<p>134、$u{款冬花}</p>\r\n<p>$q{《神农本草经》}：【款冬】味辛。温。主治咳逆上气。善喘。喉痹。诸惊痫。寒热邪气。一名橐吾。一名颗东。一名虎须。一名菟奚。生常山山谷。</p>\r\n<p>$q{《名医别录》}：【款冬】味甘。无毒。主消渴。喘息呼吸。一名氐冬。生常山及上党水傍。十一月采花。阴干。（杏仁为之使。得紫菀良。恶皂荚消石玄参。畏贝母辛夷麻黄黄芪黄芩青葙。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":133,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '134、$u{款冬花} $q{《神农本草经》}：【款冬】味辛。温。主治咳逆上气。善喘。喉痹。诸惊痫。寒热邪气。一名橐吾。一名颗东。一名虎须。一名菟奚。生常山山谷。 $q{《名医别录》}：【款冬】味甘。无毒。主消渴。喘息呼吸。一名氐冬。生常山及上党水傍。十一月采花。阴干。（杏仁为之使。得紫菀良。恶皂荚消石玄参。畏贝母辛夷麻黄黄芪黄芩青葙。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iNByjKej50u', 1, '{"title":"135、紫菀","description":"<p>135、$u{紫菀}</p>\r\n<p>$q{《神农本草经》}：【紫菀】味苦。温。主治咳逆上气。胸中寒热结气。去蛊毒、痿蹶。安五藏。生房龄山谷。</p>\r\n<p>$q{《名医别录》}：【紫菀】味辛。无毒。主治咳唾脓血。止喘悸。五劳体虚。补不足。小儿惊痫。一名紫蒨。一名青苑。生房陵及真定邯郸。二月三月采根。阴干。（款冬为之使。恶天雄瞿麦雷丸远志。畏茵陈蒿。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":134,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '135、$u{紫菀} $q{《神农本草经》}：【紫菀】味苦。温。主治咳逆上气。胸中寒热结气。去蛊毒、痿蹶。安五藏。生房龄山谷。 $q{《名医别录》}：【紫菀】味辛。无毒。主治咳唾脓血。止喘悸。五劳体虚。补不足。小儿惊痫。一名紫蒨。一名青苑。生房陵及真定邯郸。二月三月采根。阴干。（款冬为之使。恶天雄瞿麦雷丸远志。畏茵陈蒿。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rw6Mqj3o4qB', 1, '{"title":"136、泽漆","description":"<p>136、$u{泽漆}</p>\r\n<p>$q{《神农本草经》}：【泽漆】味苦。微寒。主治皮肤热。大腹水气。四肢面目浮肿。丈夫阴气不足。生太山川泽。</p>\r\n<p>$q{《名医别录》}：【泽漆】味辛。无毒。利大小肠。明目。轻身。一名漆茎。大戟苗也。生太山。三月三日七月七日采茎叶。阴干。（小豆为之使。恶署预。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":135,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '136、$u{泽漆} $q{《神农本草经》}：【泽漆】味苦。微寒。主治皮肤热。大腹水气。四肢面目浮肿。丈夫阴气不足。生太山川泽。 $q{《名医别录》}：【泽漆】味辛。无毒。利大小肠。明目。轻身。一名漆茎。大戟苗也。生太山。三月三日七月七日采茎叶。阴干。（小豆为之使。恶署预。）', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LoZ0ORbfbD5', 1, '{"title":"137、白前","description":"<p>137、$u{白前}</p>\r\n<p>$q{《名医别录》}：【白前】味甘。微温。无毒。主治胸胁逆气。咳嗽上气。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":136,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '137、$u{白前} $q{《名医别录》}：【白前】味甘。微温。无毒。主治胸胁逆气。咳嗽上气。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n6qtCRViVs3', 1, '{"title":"138、苇茎","description":"<p>138、$u{苇茎}[外台引仲景作苇叶，苇茎苇叶当为芦苇地上或水上部分，而古本草仅有芦根条。]</p>\r\n<p>$q{《名医别录》}：【芦根】味甘。寒。主治消渴。客热。止小便利。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":137,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '138、$u{苇茎}[外台引仲景作苇叶，苇茎苇叶当为芦苇地上或水上部分，而古本草仅有芦根条。] $q{《名医别录》}：【芦根】味甘。寒。主治消渴。客热。止小便利。', '2024-09-14T16:57:00.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HzvDkKxaeBg', 1, '{"title":"139、甘李根白皮","description":"<p>139、$u{甘李根白皮}</p>\r\n<p>$q{《药性论》}：【李根皮】使。苦李者入用。味咸。治脚下气。主热毒烦躁。根煮汁。止消渴。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":138,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '139、$u{甘李根白皮} $q{《药性论》}：【李根皮】使。苦李者入用。味咸。治脚下气。主热毒烦躁。根煮汁。止消渴。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MXP9ld6jAzW', 1, '{"title":"140、真朱","description":"<p>140、$u{真朱}</p>\r\n<p>$q{《神农本草经》}：【丹沙】味甘。微寒。主治身体五藏百病。养精神。安魂魄。益气。明目。杀精魅邪恶鬼。久服通神明。不老。能化为汞。生符陵山谷。</p>\r\n<p>$q{《名医别录》}：【丹沙】无毒。主通血脉。止烦满消渴。益精神。悦泽人面。除中恶腹痛毒气疥瘘诸疮。久服轻身神仙。作末名真朱。光色如云母。可析者良。生符陵。采无时。（恶磁石。畏咸水。）</p>\r\n<p>$q{《药性论》}：【丹沙】君。有大毒。镇心。主尸疰。抽风。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":139,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '140、$u{真朱} $q{《神农本草经》}：【丹沙】味甘。微寒。主治身体五藏百病。养精神。安魂魄。益气。明目。杀精魅邪恶鬼。久服通神明。不老。能化为汞。生符陵山谷。 $q{《名医别录》}：【丹沙】无毒。主通血脉。止烦满消渴。益精神。悦泽人面。除中恶腹痛毒气疥瘘诸疮。久服轻身神仙。作末名真朱。光色如云母。可析者良。生符陵。采无时。（恶磁石。畏咸水。） $q{《药性论》}：【丹沙】君。有大毒。镇心。主尸疰。抽风。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FwMZI5JA24k', 1, '{"title":"141、羊肉","description":"<p>141、$u{羊肉}</p>\r\n<p>$q{《名医别录》}：【羊肉】味甘。大热。无毒。主缓中。字乳余疾。及头脑大风汗出。虚劳寒冷。补中益气。安心止惊。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":140,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '141、$u{羊肉} $q{《名医别录》}：【羊肉】味甘。大热。无毒。主缓中。字乳余疾。及头脑大风汗出。虚劳寒冷。补中益气。安心止惊。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tlRBXVxJNxR', 1, '{"title":"142、旋覆花","description":"<p>142、$u{旋覆花}</p>\r\n<p>$q{《神农本草经》}：【旋复花】味咸。温。主治结气。胁下满。惊悸。除水。去五藏间寒热。补中下气。一名金沸草。一名盛椹。生平泽。</p>\r\n<p>$q{《名医别录》}：【旋复花】味甘。微温。冷利。有小毒。消胸上痰结唾如胶漆。心胁痰水。膀胱留饮。风气湿痹。皮间死肉。目中眵䁾。利大肠。通血脉。益色泽。一名戴椹。【根】主风湿。生平泽。五月采花。日干。廿日成。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":141,"yaoNames":"金沸草,盛椹","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '142、$u{旋覆花} $q{《神农本草经》}：【旋复花】味咸。温。主治结气。胁下满。惊悸。除水。去五藏间寒热。补中下气。一名金沸草。一名盛椹。生平泽。 $q{《名医别录》}：【旋复花】味甘。微温。冷利。有小毒。消胸上痰结唾如胶漆。心胁痰水。膀胱留饮。风气湿痹。皮间死肉。目中眵䁾。利大肠。通血脉。益色泽。一名戴椹。【根】主风湿。生平泽。五月采花。日干。廿日成。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8DXkK9AT1Pq', 1, '{"title":"143、新绛","description":"<p>143、$u{新绛}[古本草无新绛名，仅有可染绛的茜草。]</p>\r\n<p>$q{《神农本草经》}：【茜根】味苦。寒。主治寒湿风痹。黄疸。补中。久服益精气。轻身。生乔山川谷。</p>\r\n<p>$q{《名医别录》}：【茜根】无毒。主止血内崩。下血。膀胱不足。踒跌。盅毒。久服益精气。轻身。可以染绛。一名地血。一名茹藘。一名茅蒐。一名蒨。生乔山。二月三月采根。暴干。（畏鼠姑。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":142,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '143、$u{新绛}[古本草无新绛名，仅有可染绛的茜草。] $q{《神农本草经》}：【茜根】味苦。寒。主治寒湿风痹。黄疸。补中。久服益精气。轻身。生乔山川谷。 $q{《名医别录》}：【茜根】无毒。主止血内崩。下血。膀胱不足。踒跌。盅毒。久服益精气。轻身。可以染绛。一名地血。一名茹藘。一名茅蒐。一名蒨。生乔山。二月三月采根。暴干。（畏鼠姑。）', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DOm33cnbr2V', 1, '{"title":"144、葱","description":"<p>144、$u{葱}</p>\r\n<p>$q{《神农本草经》}：【葱茎】味辛。温。可作汤。主伤寒。寒热。出汗。中风。面目肿。</p>\r\n<p>$q{《名医别录》}：【葱白】平。主治寒伤。骨肉痛。喉痹不通。安胎。归目。除肝邪气。安中。利五藏。益目精。杀百药毒。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":143,"yaoNames":"葱实","aliases":[{"bieming":"葱白","name":"葱"}],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '144、$u{葱} $q{《神农本草经》}：【葱茎】味辛。温。可作汤。主伤寒。寒热。出汗。中风。面目肿。 $q{《名医别录》}：【葱白】平。主治寒伤。骨肉痛。喉痹不通。安胎。归目。除肝邪气。安中。利五藏。益目精。杀百药毒。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gZLQX87OyZG', 1, '{"title":"145、大戟","description":"<p>145、$u{大戟}</p>\r\n<p>$q{《神农本草经》}：【大戟】味苦。寒。主治蛊毒。十二水。腹满急痛。积聚。中风。皮肤疼痛。吐逆。一名邛钜。生常山。</p>\r\n<p>$q{《名医别录》}：【大戟】味甘。大寒。有小毒。主治颈腋痈肿。头痛。发汗。利大小肠。生常山。十二月采根。阴干。（反甘草。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":144,"yaoNames":"邛钜","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '145、$u{大戟} $q{《神农本草经》}：【大戟】味苦。寒。主治蛊毒。十二水。腹满急痛。积聚。中风。皮肤疼痛。吐逆。一名邛钜。生常山。 $q{《名医别录》}：【大戟】味甘。大寒。有小毒。主治颈腋痈肿。头痛。发汗。利大小肠。生常山。十二月采根。阴干。（反甘草。）', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ME53uu1RfSN', 1, '{"title":"146、芫花","description":"<p>146、$u{芫花}</p>\r\n<p>$q{《神农本草经》}：【芫花】味辛。温。主治咳逆上气。喉鸣喘。咽肿。短气。蛊毒。鬼疟。疝瘕。痈肿。杀虫鱼。一名去水。生淮源川谷。</p>\r\n<p>$q{《名医别录》}：【芫花】味苦。微温。有小毒。消胸中痰水。喜唾。水肿。五水在五藏皮肤。及腰痛。下寒毒肉毒。久服令人虚。一名毒鱼。一名牡芫。其根名蜀桑根。治疥疮。可用毒鱼。生淮源。三月三日采花。阴干。（决明为之使。反甘草。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":145,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '146、$u{芫花} $q{《神农本草经》}：【芫花】味辛。温。主治咳逆上气。喉鸣喘。咽肿。短气。蛊毒。鬼疟。疝瘕。痈肿。杀虫鱼。一名去水。生淮源川谷。 $q{《名医别录》}：【芫花】味苦。微温。有小毒。消胸中痰水。喜唾。水肿。五水在五藏皮肤。及腰痛。下寒毒肉毒。久服令人虚。一名毒鱼。一名牡芫。其根名蜀桑根。治疥疮。可用毒鱼。生淮源。三月三日采花。阴干。（决明为之使。反甘草。）', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EQ39pyP4gYo', 1, '{"title":"147、椒目","description":"<p>147、$u{椒目}</p>\r\n<p>$q{《药性论》}：【椒目】使。治十二种水气。味苦辛。有小毒。主和巴豆菖蒲松脂以蜡溶为筒子。内耳中。抽肾气虚。耳中如风水鸣。或如打钟磬之声。卒暴聋。一日一易。若神验。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":146,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '147、$u{椒目} $q{《药性论》}：【椒目】使。治十二种水气。味苦辛。有小毒。主和巴豆菖蒲松脂以蜡溶为筒子。内耳中。抽肾气虚。耳中如风水鸣。或如打钟磬之声。卒暴聋。一日一易。若神验。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VY50ulL8IK1', 1, '{"title":"148、蒲灰","description":"<p>148、$u{蒲灰}[一说为蒲黄，即香蒲花上黄粉也。另一说为败蒲席烧灰。并录之。]</p>\r\n<p>$q{《神农本草经》}：【蒲黄】味甘。平。主治心腹膀胱寒热。利小便。止血。消瘀血。久服轻身。益气力。延年神仙。生河东池泽。</p>\r\n<p>$q{《名医别录》}：【蒲黄】无毒。生河东。四月采。</p>\r\n<p>$q{《备急千金要方》}：治小便不利茎中疼痛小腹急痛方。蒲黄滑石各等分。右二味。治下筛。酒服方寸匕。日三服。</p>\r\n<p>$q{《名医别录》}：【败蒲席】平。主治筋溢恶疮。</p>\r\n<p>$q{《药性论》}：【败蒲席】亦可单用。主破血。从高坠下。损瘀在腹刺痛。此蒲合卧破败者良。取以蒲黄赤芍药当归大黄朴消煎服。血当下。</p>\r\n<p>徐彬：蒲灰。即蒲席烧灰也。能去湿热利小便。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":147,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '148、$u{蒲灰}[一说为蒲黄，即香蒲花上黄粉也。另一说为败蒲席烧灰。并录之。] $q{《神农本草经》}：【蒲黄】味甘。平。主治心腹膀胱寒热。利小便。止血。消瘀血。久服轻身。益气力。延年神仙。生河东池泽。 $q{《名医别录》}：【蒲黄】无毒。生河东。四月采。 $q{《备急千金要方》}：治小便不利茎中疼痛小腹急痛方。蒲黄滑石各等分。右二味。治下筛。酒服方寸匕。日三服。 $q{《名医别录》}：【败蒲席】平。主治筋溢恶疮。 $q{《药性论》}：【败蒲席】亦可单用。主破血。从高坠下。损瘀在腹刺痛。此蒲合卧破败者良。取以蒲黄赤芍药当归大黄朴消煎服。血当下。 徐彬：蒲灰。即蒲席烧灰也。能去湿热利小便。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Aj1WLaM2FzC', 1, '{"title":"149、戎盐","description":"<p>149、$u{戎盐}</p>\r\n<p>$q{《名医别录》}：【戎盐】味咸。寒。无毒。主心腹痛。溺血。吐血。齿舌血出。一名胡盐。生胡盐山。及西羌北地。及酒泉福禄城东南角。北海青。南海赤。十月采。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":148,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '149、$u{戎盐} $q{《名医别录》}：【戎盐】味咸。寒。无毒。主心腹痛。溺血。吐血。齿舌血出。一名胡盐。生胡盐山。及西羌北地。及酒泉福禄城东南角。北海青。南海赤。十月采。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1lOZZk4edSX', 1, '{"title":"150、白鱼","description":"<p>150、$u{白鱼}</p>\r\n<p>$q{《神农本草经》}：【衣鱼】味咸。温。主治妇人疝瘕。小便不利。小儿中风。项强背起摩之。一名白鱼。生咸阳平泽。</p>\r\n<p>$q{《名医别录》}：【衣鱼】无毒。主治淋。堕胎。涂疮。灭瘢。一名蟫。生咸阳。</p>\r\n<p>$q{《药性论》}：【衣中白鱼】使。有毒。利小便。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":149,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '150、$u{白鱼} $q{《神农本草经》}：【衣鱼】味咸。温。主治妇人疝瘕。小便不利。小儿中风。项强背起摩之。一名白鱼。生咸阳平泽。 $q{《名医别录》}：【衣鱼】无毒。主治淋。堕胎。涂疮。灭瘢。一名蟫。生咸阳。 $q{《药性论》}：【衣中白鱼】使。有毒。利小便。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9BilIvBf3q8', 1, '{"title":"151、猪膏","description":"<p>151、$u{猪膏}</p>\r\n<p>$q{《名医别录》}：【豚肪膏】主煎诸膏药。解斑蝥芫青毒。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":150,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '151、$u{猪膏} $q{《名医别录》}：【豚肪膏】主煎诸膏药。解斑蝥芫青毒。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uPYlLrb5IDD', 1, '{"title":"152、柏叶","description":"<p>152、$u{柏叶}</p>\r\n<p>$q{《名医别录》}：【柏叶】味苦。微温。无毒。主治吐血。衄血。利血。崩中。赤白。轻身。益气。令人耐风寒。去湿痹。止饥。四时各依方面采。阴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":151,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '152、$u{柏叶} $q{《名医别录》}：【柏叶】味苦。微温。无毒。主治吐血。衄血。利血。崩中。赤白。轻身。益气。令人耐风寒。去湿痹。止饥。四时各依方面采。阴干。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SCF7V1K3nf8', 1, '{"title":"153、马通汁","description":"<p>153、$u{马通汁}</p>\r\n<p>$q{《名医别录》}：【马通】微温。治妇人崩中。止渴。及吐下血。鼻衄。金创。止血。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":152,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '153、$u{马通汁} $q{《名医别录》}：【马通】微温。治妇人崩中。止渴。及吐下血。鼻衄。金创。止血。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u06nRa7vamN', 1, '{"title":"154、灶心黄土","description":"<p>154、$u{灶心黄土}（黄土）</p>\r\n<p>$q{《名医别录》}：【伏龙肝】味辛。微温。主治妇人崩中。吐下血。止咳逆。止血。消痈肿毒气。</p>\r\n<p>$q{《药性论》}∶【伏龙肝】单用亦可。味咸。无毒。末与醋调。涂痈肿。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":153,"yaoNames":"灶中黄土,黄土,伏龙肝","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '154、$u{灶心黄土}（黄土） $q{《名医别录》}：【伏龙肝】味辛。微温。主治妇人崩中。吐下血。止咳逆。止血。消痈肿毒气。 $q{《药性论》}∶【伏龙肝】单用亦可。味咸。无毒。末与醋调。涂痈肿。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lnCeUKi7Ud2', 1, '{"title":"155、诃梨勒","description":"<p>155、$u{诃梨勒}</p>\r\n<p>$q{《新修本草》}：【诃梨勒】味苦。温。无毒。主冷气心腹胀满。下宿物。生交爱州。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":154,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '155、$u{诃梨勒} $q{《新修本草》}：【诃梨勒】味苦。温。无毒。主冷气心腹胀满。下宿物。生交爱州。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oHXa471JIIR', 1, '{"title":"156、败酱","description":"<p>156、$u{败酱}</p>\r\n<p>$q{《神农本草经》}：【败酱】味苦。平。主治暴热。火疮。赤气。疥瘙。疽。痔。马鞍热气。一名鹿肠。生江夏川谷。</p>\r\n<p>$q{《名医别录》}：【败酱】味咸。微寒。无毒。主除痈肿。浮肿。结热。风痹。不足。产后疾痛。一名鹿首。名马草。一名泽败。生江夏。八月采根。暴干。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":155,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '156、$u{败酱} $q{《神农本草经》}：【败酱】味苦。平。主治暴热。火疮。赤气。疥瘙。疽。痔。马鞍热气。一名鹿肠。生江夏川谷。 $q{《名医别录》}：【败酱】味咸。微寒。无毒。主除痈肿。浮肿。结热。风痹。不足。产后疾痛。一名鹿首。名马草。一名泽败。生江夏。八月采根。暴干。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w5Ef5GxAVGF', 1, '{"title":"157、桑东南根白皮","description":"<p>157、$u{桑东南根白皮}（桑根皮）</p>\r\n<p>$q{《神农本草经》}：【桑根白皮】味甘。寒。主治伤中。五劳。六极。羸瘦。崩中。脉绝。补虚。益气。生犍为山谷。</p>\r\n<p>$q{《名医别录》}：【桑根白皮】无毒。主去肺中水气。止唾血。热渴。水肿。腹满。胪胀。利水道。去寸白。可以缝金创。采无时。出土上者杀人。（续断桂心麻子为之使。叶汁解蜈蚣毒。）</p>\r\n<p>$q{《药性论》}：【桑白皮】使。平。能治肺气喘满。水气浮肿。主伤绝。利水道。消水气。虚劳客热头痛。内补不足。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":156,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '157、$u{桑东南根白皮}（桑根皮） $q{《神农本草经》}：【桑根白皮】味甘。寒。主治伤中。五劳。六极。羸瘦。崩中。脉绝。补虚。益气。生犍为山谷。 $q{《名医别录》}：【桑根白皮】无毒。主去肺中水气。止唾血。热渴。水肿。腹满。胪胀。利水道。去寸白。可以缝金创。采无时。出土上者杀人。（续断桂心麻子为之使。叶汁解蜈蚣毒。） $q{《药性论》}：【桑白皮】使。平。能治肺气喘满。水气浮肿。主伤绝。利水道。消水气。虚劳客热头痛。内补不足。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('adsjGVQlMyg', 1, '{"title":"158、王不留行","description":"<p>158、$u{王不留行}</p>\r\n<p>$q{《神农本草经》}：【王不留行】味苦。主治金创。止血。逐痛。出刺。除风痹内寒。久服轻身。耐老。增寿。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【王不留行】味甘。平。无毒。止心烦。鼻衄。痈疽。恶疮。瘘乳。妇人难产。生太山。二月八月采。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":157,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '158、$u{王不留行} $q{《神农本草经》}：【王不留行】味苦。主治金创。止血。逐痛。出刺。除风痹内寒。久服轻身。耐老。增寿。生太山山谷。 $q{《名医别录》}：【王不留行】味甘。平。无毒。止心烦。鼻衄。痈疽。恶疮。瘘乳。妇人难产。生太山。二月八月采。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('56TOGorPcq0', 1, '{"title":"159、蒴藋细叶","description":"<p>159、$u{蒴藋细叶}</p>\r\n<p>$q{《名医别录》}：【蒴藋】味酸。温。有毒。主治风瘙瘾疹身痒湿痹。可作浴汤。一名堇草。一名芨。生田野。春夏采叶。秋冬采茎根。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":158,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '159、$u{蒴藋细叶} $q{《名医别录》}：【蒴藋】味酸。温。有毒。主治风瘙瘾疹身痒湿痹。可作浴汤。一名堇草。一名芨。生田野。春夏采叶。秋冬采茎根。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a1Gsa4iw2MF', 1, '{"title":"160、藜芦","description":"<p>160、$u{藜芦}</p>\r\n<p>$q{《神农本草经》}：【藜芦】味辛。寒。主治蛊毒。咳逆。泄痢。肠澼。头疡。疥瘙。恶疮。杀诸虫毒。去死肌。一名葱苒。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【藜芦】味苦。微寒。有毒。主治啘逆。喉痹不通。鼻中息肉。马刀烂疮。不入汤。一名葱菼。一名山葱。生太山。三月采根。阴干。（黄连为之使。反细辛芍药五参。恶大黄。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":159,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '160、$u{藜芦} $q{《神农本草经》}：【藜芦】味辛。寒。主治蛊毒。咳逆。泄痢。肠澼。头疡。疥瘙。恶疮。杀诸虫毒。去死肌。一名葱苒。生太山山谷。 $q{《名医别录》}：【藜芦】味苦。微寒。有毒。主治啘逆。喉痹不通。鼻中息肉。马刀烂疮。不入汤。一名葱菼。一名山葱。生太山。三月采根。阴干。（黄连为之使。反细辛芍药五参。恶大黄。）', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r5npGXNk8eW', 1, '{"title":"161、鸡屎白","description":"<p>161、$u{鸡屎白}</p>\r\n<p>$q{《神农本草经》}：【鸡屎白】主治消渴。伤寒。寒热。</p>\r\n<p>$q{《名医别录》}：【鸡矢白】微寒。破石淋及转筋。利小便。止遗溺。灭瘢痕。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":160,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '161、$u{鸡屎白} $q{《神农本草经》}：【鸡屎白】主治消渴。伤寒。寒热。 $q{《名医别录》}：【鸡矢白】微寒。破石淋及转筋。利小便。止遗溺。灭瘢痕。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fUxMXp8r0aZ', 1, '{"title":"162、蜘蛛","description":"<p>162、$u{蜘蛛}</p>\r\n<p>$q{《名医别录》}：【蜘蛛】微寒。主治大人小儿㿉。七月七日取其网。治喜忘。又。疗小儿大腹丁奚。三年不能行者。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":161,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '162、$u{蜘蛛} $q{《名医别录》}：【蜘蛛】微寒。主治大人小儿㿉。七月七日取其网。治喜忘。又。疗小儿大腹丁奚。三年不能行者。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ghsn25eutF9', 1, '{"title":"163、白粉","description":"<p>163、$u{白粉}（粉）[据二千金当为梁米粉，外台引千金翼作白梁粉，可从。]</p>\r\n<p>$q{《名医别录》}：【青梁米】味甘。微寒。无毒。主治胃瘅。热中。消渴。止泄痢。利小便。益气。补中。轻身。长年。</p>\r\n<p>$q{《名医别录》}：【黄梁米】味甘。平。无毒。主益气。和中。止泄。</p>\r\n<p>$q{《名医别录》}：【白梁米】味甘。微寒。无毒。主除热。益气。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":162,"yaoNames":"","aliases":[{"bieming":"粉","name":"白粉"}],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '163、$u{白粉}（粉）[据二千金当为梁米粉，外台引千金翼作白梁粉，可从。] $q{《名医别录》}：【青梁米】味甘。微寒。无毒。主治胃瘅。热中。消渴。止泄痢。利小便。益气。补中。轻身。长年。 $q{《名医别录》}：【黄梁米】味甘。平。无毒。主益气。和中。止泄。 $q{《名医别录》}：【白梁米】味甘。微寒。无毒。主除热。益气。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ld2CqoYXh1L', 1, '{"title":"164、乌梅","description":"<p>164、$u{乌梅}</p>\r\n<p>$q{《神农本草经》}：【梅实】味酸。平。主下气。除热烦满。安心。肢体痛。偏枯。不仁死肌。去青黑痣恶疾。生汉中川谷。</p>\r\n<p>$q{《名医别录》}：【梅实】无毒。止下痢。好唾。口干。生漠中。五月采。火干。又【梅根】疗风痹。出土者杀人。【梅实】利筋脉。去痹。</p>\r\n<p>$q{《本草图经》}：五月采其黄实。火熏干。作乌梅。</p>\r\n<p>$q{《本草衍义》}：燻之为乌梅。暴干藏密器中为白梅。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":163,"yaoNames":"梅实","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '164、$u{乌梅} $q{《神农本草经》}：【梅实】味酸。平。主下气。除热烦满。安心。肢体痛。偏枯。不仁死肌。去青黑痣恶疾。生汉中川谷。 $q{《名医别录》}：【梅实】无毒。止下痢。好唾。口干。生漠中。五月采。火干。又【梅根】疗风痹。出土者杀人。【梅实】利筋脉。去痹。 $q{《本草图经》}：五月采其黄实。火熏干。作乌梅。 $q{《本草衍义》}：燻之为乌梅。暴干藏密器中为白梅。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4WqGFUUR22E', 1, '{"title":"165、葵子","description":"<p>165、$u{葵子}</p>\r\n<p>$q{《神农本草经》}：【冬葵子】味甘。寒。主治五藏六府寒热。羸瘦。五癃。利小便。久服坚骨。长肌肉。轻身。延年。生少室山。</p>\r\n<p>$q{《名医别录》}：【冬葵子】无毒。主治妇人乳难内闭。生少室。十二月采。（黄芩为之使。）</p>\r\n<p>$q{《本草经集注》}：【冬葵子】至滑利。能下石。</p>\r\n<p>$q{《药性论》}：【冬葵子】臣。滑。平。能治五淋。主奶肿。能下乳汁。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":164,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '165、$u{葵子} $q{《神农本草经》}：【冬葵子】味甘。寒。主治五藏六府寒热。羸瘦。五癃。利小便。久服坚骨。长肌肉。轻身。延年。生少室山。 $q{《名医别录》}：【冬葵子】无毒。主治妇人乳难内闭。生少室。十二月采。（黄芩为之使。） $q{《本草经集注》}：【冬葵子】至滑利。能下石。 $q{《药性论》}：【冬葵子】臣。滑。平。能治五淋。主奶肿。能下乳汁。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AAufH0ElVIH', 1, '{"title":"166、竹叶","description":"<p>166、$u{竹叶}</p>\r\n<p>$q{《神农本草经》}：【竹叶】味苦。平。主治咳逆上气。溢筋急。恶疡。杀小虫。【根】作汤。益气。止渴。补虚。下气。【汁】治风痓痹。【实】通神明。轻身。益气。生益州。</p>\r\n<p>$q{《名医别录》}：【芹竹叶】大寒。无毒。主除烦热。风痓。喉痹。呕逆。【根】消毒。生益州。</p>\r\n<p>$q{《名医别录》}：【淡竹叶】味辛。平。大寒。主治胸中淡热。咳逆上气。其【沥】大寒。治暴中风。风痹。胸中大热。止烦闷。其【皮茹】微寒。主治呕啘。温气寒热。吐血。崩中。溢筋。</p>\r\n<p>$q{《名医别录》}：【苦竹叶及沥】治口疮。目痛明目。通利九窍。【竹笋】味甘。无毒。主消渴。利水道。益气。可久食。【干笋】烧服。治五痔血。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":165,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '166、$u{竹叶} $q{《神农本草经》}：【竹叶】味苦。平。主治咳逆上气。溢筋急。恶疡。杀小虫。【根】作汤。益气。止渴。补虚。下气。【汁】治风痓痹。【实】通神明。轻身。益气。生益州。 $q{《名医别录》}：【芹竹叶】大寒。无毒。主除烦热。风痓。喉痹。呕逆。【根】消毒。生益州。 $q{《名医别录》}：【淡竹叶】味辛。平。大寒。主治胸中淡热。咳逆上气。其【沥】大寒。治暴中风。风痹。胸中大热。止烦闷。其【皮茹】微寒。主治呕啘。温气寒热。吐血。崩中。溢筋。 $q{《名医别录》}：【苦竹叶及沥】治口疮。目痛明目。通利九窍。【竹笋】味甘。无毒。主消渴。利水道。益气。可久食。【干笋】烧服。治五痔血。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uwe852yGS58', 1, '{"title":"167、白薇","description":"<p>167、$u{白薇}</p>\r\n<p>$q{《神农本草经》}：【白薇】味苦。平。主治暴中风。身热。肢满。忽忽不知人。狂惑邪气。寒热酸疼。温疟洗洗发作有时。生平原川谷。</p>\r\n<p>$q{《名医别录》}：【白薇】味咸。大寒。无毒。主治伤中淋露。下水气。利阴气。益精。一名白幕。一名薇草。一名春草。一名骨美。久服利人。生平原。三月三日采根。阴干。（恶黄芪干姜干漆山茱萸大枣。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":166,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '167、$u{白薇} $q{《神农本草经》}：【白薇】味苦。平。主治暴中风。身热。肢满。忽忽不知人。狂惑邪气。寒热酸疼。温疟洗洗发作有时。生平原川谷。 $q{《名医别录》}：【白薇】味咸。大寒。无毒。主治伤中淋露。下水气。利阴气。益精。一名白幕。一名薇草。一名春草。一名骨美。久服利人。生平原。三月三日采根。阴干。（恶黄芪干姜干漆山茱萸大枣。）', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VJgLk49jilU', 1, '{"title":"168、柏实","description":"<p>168、$u{柏实}</p>\r\n<p>$q{《神农本草经》}：【柏子】味甘。平。无毒。主治惊悸。安五藏。益气。除风湿痹。久服令人润泽美色。耳目聪明。不饥。不老。轻身。延年。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【柏实】无毒。主治恍惚虚损。吸吸历节。腰中重痛。益血。止汗。生太山。柏叶尤良。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":167,"yaoNames":"","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '168、$u{柏实} $q{《神农本草经》}：【柏子】味甘。平。无毒。主治惊悸。安五藏。益气。除风湿痹。久服令人润泽美色。耳目聪明。不饥。不老。轻身。延年。生太山山谷。 $q{《名医别录》}：【柏实】无毒。主治恍惚虚损。吸吸历节。腰中重痛。益血。止汗。生太山。柏叶尤良。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N3dS9Qrr2yS', 1, '{"title":"169、苏叶","description":"<p>169、$u{苏叶}</p>\r\n<p>$q{《名医别录》}：【苏】味辛。温。主下气。除寒中。其子尤良。</p>\r\n<p>$q{《药性论》}：【紫苏子】无毒。主上气咳逆。治冷气及腰脚中湿风结气。将子研汁煮粥良。长服令人肥白身香。和高良姜橘皮等分蜜丸。空心下十丸。下一切宿冷气。及脚湿气。</p>\r\n<p>$q{《药性论》}：【紫苏叶】可生食。与一切鱼肉作羹。良。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":168,"yaoNames":"","aliases":[{"bieming":"干苏叶","name":"苏叶"}],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '169、$u{苏叶} $q{《名医别录》}：【苏】味辛。温。主下气。除寒中。其子尤良。 $q{《药性论》}：【紫苏子】无毒。主上气咳逆。治冷气及腰脚中湿风结气。将子研汁煮粥良。长服令人肥白身香。和高良姜橘皮等分蜜丸。空心下十丸。下一切宿冷气。及脚湿气。 $q{《药性论》}：【紫苏叶】可生食。与一切鱼肉作羹。良。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jmwsTRL4bR2', 1, '{"title":"170、土瓜根","description":"<p>170、$u{土瓜根}</p>\r\n<p>$q{《神农本草经》}：【王瓜】味苦。寒。主治消渴。内痹。瘀血。月闭。寒热。酸疼。益气。愈聋。一名土瓜。生鲁地平泽。</p>\r\n<p>$q{《名医别录》}：【王瓜】无毒。主治诸邪气。热结。鼠瘘。散痈肿留血。妇人带下不通。下乳汁。止小便数不禁。逐四肢骨节中水。治马骨刺入疮。生鲁地田野及人家垣墙间。三月采根。阴干。</p>\r\n<p>$q{《药性论》}：【土瓜根】使。平。一名王瓜。子主蛊毒。治小便数。遗不禁。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":169,"yaoNames":"王瓜,土瓜","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '170、$u{土瓜根} $q{《神农本草经》}：【王瓜】味苦。寒。主治消渴。内痹。瘀血。月闭。寒热。酸疼。益气。愈聋。一名土瓜。生鲁地平泽。 $q{《名医别录》}：【王瓜】无毒。主治诸邪气。热结。鼠瘘。散痈肿留血。妇人带下不通。下乳汁。止小便数不禁。逐四肢骨节中水。治马骨刺入疮。生鲁地田野及人家垣墙间。三月采根。阴干。 $q{《药性论》}：【土瓜根】使。平。一名王瓜。子主蛊毒。治小便数。遗不禁。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c5sh4uVB3zl', 1, '{"title":"171、红蓝花","description":"<p>171、$u{红蓝花}</p>\r\n<p>$q{《开宝本草》}：【红蓝花】味辛。温。无毒。主产后血运口噤。腹内恶血不尽。绞痛。胎死腹中。并酒煮服。亦主蛊毒下血。堪作燕脂。生梁汉及西域。一名黄蓝。</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":170,"yaoNames":"黄蓝","aliases":[],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '171、$u{红蓝花} $q{《开宝本草》}：【红蓝花】味辛。温。无毒。主产后血运口噤。腹内恶血不尽。绞痛。胎死腹中。并酒煮服。亦主蛊毒下血。堪作燕脂。生梁汉及西域。一名黄蓝。', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lMDTFwL4kfg', 1, '{"title":"172、蛇床子","description":"<p>172、$u{蛇床子}（蛇床子仁）</p>\r\n<p>$q{《神农本草经》}：【蛇床子】味苦。平。主治妇人阴中肿痛。男子阴痿湿痒。除痹气。利关节。治癫痫。恶疮。久服轻身。一名蛇粟。一名蛇米。生临淄川谷。</p>\r\n<p>$q{《名医别录》}：【蛇床子】味辛甘。无毒。主温中下气。令妇人子藏热。男子阴强。久服好颜色。令人有子。一名虺床。一名思益。一名绳毒。一名枣棘。一名墙蘼。生临淄。五月采实。阴干。（恶牡丹巴豆贝母。）</p>","content_format":"html","_microfeed":{"bookId":"4KbG9bDqdz3","bieMing":"","no":171,"yaoNames":"蛇床子仁,虺床,思益,绳毒,枣棘,墙蘼","aliases":[{"bieming":"蛇床子仁","name":"蛇床子"}],"volume":"中药"}}', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '2024-09-14T16:57:01.000Z', '172、$u{蛇床子}（蛇床子仁） $q{《神农本草经》}：【蛇床子】味苦。平。主治妇人阴中肿痛。男子阴痿湿痒。除痹气。利关节。治癫痫。恶疮。久服轻身。一名蛇粟。一名蛇米。生临淄川谷。 $q{《名医别录》}：【蛇床子】味辛甘。无毒。主温中下气。令妇人子藏热。男子阴强。久服好颜色。令人有子。一名虺床。一名思益。一名绳毒。一名枣棘。一名墙蘼。生临淄。五月采实。阴干。（恶牡丹巴豆贝母。）', '2024-09-14T16:57:01.000Z', 1, NULL, '4KbG9bDqdz3', 'yao', 'F5Pf7dvj0rJ');
